const staticEconomicsQuestions = [

  // ===================== BASIC CONCEPTS & SECTORS =====================
  { id: 'eco-001', category: 'Economics - Structural Change', question: 'Which statement best reflects the failure of structural transformation in Indian agriculture between 1950 and 1990?', options: ['Agricultural GDP doubled', 'Agricultural workforce declined rapidly', 'Industrial sector absorbed the surplus labour', 'About 65% of the population remained dependent on agriculture'], answer: 3, explanation: 'Even though agriculture\'s share in GDP fell, around 65% of the population continued to depend on agriculture, showing that structural transformation (shift of labour to industry/services) failed to happen.' },
  { id: 'eco-002', category: 'Economics - Sectors', question: 'Which sector of the Indian economy provides the highest employment but contributes the least to GDP?', options: ['Secondary sector', 'Tertiary sector', 'Primary sector', 'Quaternary sector'], answer: 2, explanation: 'The primary sector (agriculture, mining, fishing, forestry) employs the largest share of the population but contributes the least to GDP.' },
  { id: 'eco-003', category: 'Economics - Sectors', question: 'Which sector is called the "backbone of industrialisation" and contributes significantly to GDP growth?', options: ['Primary sector', 'Secondary sector', 'Tertiary sector', 'Quinary sector'], answer: 1, explanation: 'The secondary sector consists of manufacturing and heavy industries and is regarded as the backbone of industrialisation.' },
  { id: 'eco-004', category: 'Economics - Sectors', question: 'As per Census 2011 data, which sector contributes the largest share to India\'s GDP?', options: ['Primary sector', 'Secondary sector', 'Tertiary (service) sector', 'Quaternary sector'], answer: 2, explanation: 'The tertiary/service sector contributes about 54% of India\'s GDP, the largest share, despite employing a relatively smaller workforce.' },
  { id: 'eco-005', category: 'Economics - Sectors', question: 'The term used for the shift of workers from agriculture to industry and services is:', options: ['Industrialisation', 'Urbanisation', 'Occupational Diversification', 'Economic Transition'], answer: 2, explanation: 'This shift of workers changing their occupation from agriculture to industry/services is called Occupational Diversification.' },
  { id: 'eco-006', category: 'Economics - Sectors', question: 'Which sector includes knowledge and information-based services like IT, R&D, consultancy and financial planning?', options: ['Secondary sector', 'Tertiary sector', 'Quaternary sector', 'Quinary sector'], answer: 2, explanation: 'The Quaternary sector covers knowledge-based services such as IT, R&D, consultancy and financial planning.' },
  { id: 'eco-007', category: 'Economics - Sectors', question: 'High-level decision-making jobs such as top executives, CEOs and policy makers fall under which sector?', options: ['Tertiary sector', 'Quaternary sector', 'Quinary sector', 'Secondary sector'], answer: 2, explanation: 'The Quinary sector includes high-level decision-making roles like CEOs, government officials and policy makers.' },

  // ===================== TYPES OF ECONOMY =====================
  { id: 'eco-008', category: 'Economics - Types of Economy', question: 'Which type of economy is characterised by dominance of private ownership and profit motive with limited government interference?', options: ['Socialist economy', 'Mixed economy', 'Capitalist economy', 'Command economy'], answer: 2, explanation: 'In a capitalist economy, private ownership dominates, prices are determined by demand and supply, and the profit motive drives the market.' },
  { id: 'eco-009', category: 'Economics - Types of Economy', question: 'In which type of economy is the entire market controlled by the government with the motive of people\'s welfare rather than profit?', options: ['Capitalist economy', 'Socialist economy', 'Mixed economy', 'Market economy'], answer: 1, explanation: 'In a socialist economy, centralised planning by government exists and the motive is welfare of people, not profit.' },
  { id: 'eco-010', category: 'Economics - Types of Economy', question: 'India and China are examples of which type of economy where both private and public sectors operate simultaneously?', options: ['Capitalist economy', 'Socialist economy', 'Mixed economy', 'Traditional economy'], answer: 2, explanation: 'A mixed economy has both private and public sectors working in parallel, providing consumers a large variety of choices.' },

  // ===================== DEMAND, SUPPLY & ELASTICITY =====================
  { id: 'eco-011', category: 'Economics - Law of Demand', question: 'Which statement correctly describes the Law of Demand?', options: ['When price increases, demand also increases', 'When price decreases, demand also decreases', 'When price increases, demand decreases (other things being constant)', 'Price has no effect on demand'], answer: 2, explanation: 'The Law of Demand states that when the price of a commodity rises, its demand falls, other things remaining constant (ceteris paribus), based on income effect and substitution effect.' },
  { id: 'eco-012', category: 'Economics - Law of Demand', question: 'The Law of Demand is based on which two effects?', options: ['Income effect and Substitution effect', 'Wealth effect and Price effect', 'Interest effect and Tax effect', 'Demand effect and Supply effect'], answer: 0, explanation: 'The Law of Demand operates through the Income Effect (change in purchasing power) and the Substitution Effect (switching to substitute goods).' },
  { id: 'eco-013', category: 'Economics - Exceptions to Law of Demand', question: 'Which of the following is NOT an exception to the Law of Demand?', options: ['Giffen goods', 'Veblen goods (Conspicuous goods)', 'Speculative goods', 'Substitute goods'], answer: 3, explanation: 'Substitute goods follow the normal Law of Demand — when price rises, consumers shift to substitutes and demand falls. Giffen goods, Veblen goods and speculative goods are exceptions.' },
  { id: 'eco-014', category: 'Economics - Types of Goods', question: 'Daily necessities like rice, wheat and petrol, whose demand does not fall even when prices rise, are called:', options: ['Veblen goods', 'Giffen goods', 'Complementary goods', 'Inferior goods only'], answer: 1, explanation: 'Giffen goods are essential, daily-use goods for which demand does not fall significantly even if prices rise.' },
  { id: 'eco-015', category: 'Economics - Types of Goods', question: 'Luxury items like iPhones, Rolex watches and sports cars, whose demand does not fall despite rising prices because they act as status symbols, are known as:', options: ['Giffen goods', 'Veblen goods (Conspicuous goods)', 'Normal goods', 'Complementary goods'], answer: 1, explanation: 'Veblen goods (also called conspicuous goods) are luxury items where higher price does not reduce demand because they signal status.' },
  { id: 'eco-016', category: 'Economics - Types of Goods', question: 'Goods like gold, purchased in anticipation of a future price rise even without immediate need, are called:', options: ['Veblen goods', 'Speculative goods', 'Giffen goods', 'Substitute goods'], answer: 1, explanation: 'Speculative goods (e.g., gold, property) are bought in expectation that prices will rise in the future, not out of immediate necessity.' },
  { id: 'eco-017', category: 'Economics - Types of Goods', question: 'Goods like Thums Up and Pepsi, or Surf Excel and Nirma, which can replace each other, are known as:', options: ['Complementary goods', 'Substitute goods', 'Giffen goods', 'Veblen goods'], answer: 1, explanation: 'Substitute goods serve the same purpose and can replace one another, e.g., Thums Up and Pepsi, or Surf Excel and Nirma.' },
  { id: 'eco-018', category: 'Economics - Types of Goods', question: 'Goods like a mobile phone and its cover, or a car and its tyres, which are used together, are called:', options: ['Substitute goods', 'Complementary goods', 'Giffen goods', 'Veblen goods'], answer: 1, explanation: 'Complementary goods are used together — one supports the demand of the other, such as pen and refill, or bat and ball.' },
  { id: 'eco-019', category: 'Economics - Curves', question: 'Which curve shows the relationship between price and quantity demanded, and slopes downward from left to right?', options: ['Supply curve', 'Demand curve', 'Production curve', 'Cost curve'], answer: 1, explanation: 'The Demand curve slopes downward, showing that as price falls, quantity demanded rises.' },
  { id: 'eco-020', category: 'Economics - Curves', question: 'Which curve slopes upward from left to right, showing that as price rises, quantity supplied also rises (best example: gold)?', options: ['Demand curve', 'Supply curve', 'Indifference curve', 'Lorenz curve'], answer: 1, explanation: 'The Supply curve slopes upward — as prices increase, sellers are willing to supply more, e.g. gold.' },
  { id: 'eco-021', category: 'Economics - Curves', question: 'Which curve represents combinations of two goods that give equal satisfaction and never intersect each other?', options: ['Lorenz curve', 'Indifference curve', 'Phillips curve', 'Laffer curve'], answer: 1, explanation: 'The Indifference curve shows combinations of two goods giving equal satisfaction; different indifference curves never intersect (e.g., Mercedes vs BMW buyers).' },
  { id: 'eco-022', category: 'Economics - Curves', question: 'Which curve shows that beyond a certain point, increasing the tax rate leads to a decline in government revenue?', options: ['Phillips curve', 'Laffer curve', 'Kuznets curve', 'Lorenz curve'], answer: 1, explanation: 'The Laffer curve depicts the relationship between tax rate and tax revenue — revenue rises with tax rate up to a point, then falls.' },
  { id: 'eco-023', category: 'Economics - Curves', question: 'Which downward-sloping curve shows the relationship between unemployment and inflation?', options: ['Laffer curve', 'Phillips curve', 'Kuznets curve', 'Engel curve'], answer: 1, explanation: 'The Phillips curve shows an inverse relationship between unemployment and inflation — when inflation is high, unemployment tends to be low, and vice versa.' },
  { id: 'eco-024', category: 'Economics - Curves', question: 'Which curve shows the inverted-U relationship between economic growth (per capita income) and inequality?', options: ['Lorenz curve', 'Phillips curve', 'Kuznets curve', 'Laffer curve'], answer: 2, explanation: 'The Kuznets curve shows an inverted-U relationship between per capita income (growth) and inequality.' },
  { id: 'eco-025', category: 'Economics - Elasticity', question: 'If the price of a commodity increases by 10% and its demand falls by 20%, this is classified as:', options: ['Inelastic demand', 'Elastic demand', 'Unitary elastic demand', 'Perfectly inelastic demand'], answer: 1, explanation: 'Since the percentage change in quantity demanded (20%) is greater than the percentage change in price (10%), elasticity is greater than 1, i.e., elastic demand.' },
  { id: 'eco-026', category: 'Economics - Elasticity', question: 'Necessities like salt and medicine, whose demand does not change much even with a price change, exhibit which type of demand?', options: ['Elastic demand', 'Inelastic demand', 'Unitary elastic demand', 'Perfectly elastic demand'], answer: 1, explanation: 'Inelastic demand is seen in necessities such as salt and medicine, where demand remains largely unaffected by price changes.' },
  { id: 'eco-027', category: 'Economics - Elasticity', question: 'Luxury goods like diamonds, where demand becomes zero even with a slight increase in price, exhibit:', options: ['Perfectly inelastic demand', 'Perfectly elastic demand', 'Unitary elastic demand', 'Inelastic demand'], answer: 1, explanation: 'In perfectly elastic demand, even a small rise in price causes demand to fall to zero, typical of highly price-sensitive niche luxury markets like movie tickets priced too high.' },
  { id: 'eco-028', category: 'Economics - Elasticity', question: 'In liquidity trap conditions, the demand for money with respect to interest rate is:', options: ['Perfectly inelastic', 'Perfectly elastic', 'Unitary elastic', 'Zero'], answer: 1, explanation: 'A liquidity trap is characterised by perfectly elastic demand for money with respect to interest rate, making monetary policy ineffective.' },
  { id: 'eco-029', category: 'Economics - Liquidity Trap', question: 'In a liquidity trap, what do people generally prefer to do with their money?', options: ['Invest heavily in stocks', 'Hold cash instead of investing', 'Deposit maximum money in banks', 'Spend it immediately on luxury goods'], answer: 1, explanation: 'In a liquidity trap, during economic downturns, people prefer to hold cash instead of investing, making monetary policy ineffective (e.g., during COVID-19 pandemic).' , notes: ["liquidity trap theory = john maynard keynes\ninvisible hand theory = adam smith,\nan enquiry into wealth of nation= adam smith"],},

  // ===================== MARKET STRUCTURES =====================
  { id: 'eco-030', category: 'Economics - Market Structures', question: 'Which market structure is characterised by many buyers and sellers, homogeneous products, and firms being "price takers"?', options: ['Monopoly', 'Perfect Competition', 'Oligopoly', 'Monopolistic Competition'], answer: 1, explanation: 'Perfect competition has many buyers/sellers, homogeneous goods, free entry-exit, and firms are price takers, with only normal profit in the long run.' },
  { id: 'eco-031', category: 'Economics - Market Structures', question: 'A market with a single seller, no close substitutes, and high entry barriers, where the firm is a "price maker", is called:', options: ['Perfect Competition', 'Monopoly', 'Monopolistic Competition', 'Monopsony'], answer: 1, explanation: 'Monopoly has a single seller with no close substitutes and high entry barriers; the firm can set its own price (price maker) and earn super-normal profits.' },
  { id: 'eco-032', category: 'Economics - Market Structures', question: 'A market with many sellers offering differentiated products (e.g., food stalls of different cuisines) is called:', options: ['Oligopoly', 'Monopolistic Competition', 'Perfect Competition', 'Monopsony'], answer: 1, explanation: 'Monopolistic competition has many sellers with differentiated products; firms may earn super-normal profit in the short run but only normal profit in the long run.' },
  { id: 'eco-033', category: 'Economics - Market Structures', question: 'A market dominated by a few large, aggressive firms with high interdependence and high entry barriers (e.g., telecom sector) is called:', options: ['Monopoly', 'Oligopoly', 'Monopolistic Competition', 'Perfect Competition'], answer: 1, explanation: 'Oligopoly is dominated by a few large firms (e.g., Jio, Airtel, Vodafone in telecom) with high interdependence and entry barriers.' },
  { id: 'eco-034', category: 'Economics - Market Structures', question: 'A market situation with a single buyer and many sellers, giving the buyer full bargaining power, is called:', options: ['Monopoly', 'Oligopoly', 'Monopsony', 'Duopoly'], answer: 2, explanation: 'In a Monopsony, there is a single buyer and many sellers, giving the buyer full bargaining power (e.g., a single major employer in a town).' },
  { id: 'eco-035', category: 'Economics - Market Structures', question: 'Which of the following is NOT an assumption of perfect competition?', options: ['There are many buyers and sellers', 'The goods sold by all sellers are homogeneous', 'Buyers and sellers have perfect information', 'The average total cost continuously decreases'], answer: 3, explanation: 'Continuously decreasing average total cost is not an assumption of perfect competition; it would lead to market failure/collapse rather than being a market characteristic.' },
  { id: 'eco-036', category: 'Economics - Microeconomics', question: 'Price theory is another name for which branch of economics?', options: ['Macroeconomics', 'Microeconomics', 'Development economics', 'Welfare economics'], answer: 1, explanation: 'Price theory operates in Microeconomics, where firms aim to maximise profit and price plays a central role in decision-making.' },

  // ===================== NATIONAL INCOME =====================
  { id: 'eco-037', category: 'Economics - National Income', question: 'Who first scientifically estimated the National Income of India?', options: ['Dadabhai Naoroji', 'V.K.R.V. Rao', 'Amartya Sen', 'P.C. Mahalanobis'], answer: 1, explanation: 'V.K.R.V. Rao gave the first scientific estimate of India\'s National Income in 1931-32 and is known as the Father of National Income Accounting of India.' },
  { id: 'eco-038', category: 'Economics - National Income', question: 'Who first propounded the concept of national income/wealth (Drain of Wealth theory) in India, even though not scientifically?', options: ['V.K.R.V. Rao', 'Dadabhai Naoroji', 'M.S. Swaminathan', 'Amartya Sen'], answer: 1, explanation: 'Dadabhai Naoroji gave the Drain of Wealth theory in 1867-68, describing how British rule was draining India\'s wealth, though it was not a scientific estimate.' },
  { id: 'eco-039', category: 'Economics - National Income', question: 'To move from Market Cost to Factor Cost, what must be done?', options: ['Add Indirect Tax', 'Subtract Indirect Tax', 'Add Subsidy', 'Subtract Depreciation'], answer: 1, explanation: 'Factor Cost = Market Cost − Indirect Tax (+ Subsidy). Removing indirect tax from market cost gives factor cost.' },
  { id: 'eco-040', category: 'Economics - National Income', question: 'To move from GDP (Gross) to NDP (Net), what must be subtracted?', options: ['Indirect tax', 'Subsidy', 'Depreciation', 'Net Income from Abroad'], answer: 2, explanation: 'NDP = GDP − Depreciation. Depreciation represents the wear and tear/loss in value of capital assets.' },
  { id: 'eco-041', category: 'Economics - National Income', question: 'Which of the following correctly represents the calculation of National Income in three steps?', options: ['GDP → NDP → NNP (Factor Cost)', 'GNP → GDP → NDP', 'NNP → NDP → GDP', 'GDP → GNP → Factor Cost only'], answer: 0, explanation: 'National Income = GDP − Depreciation (→NDP) + Net Income from Abroad (→NNP at Market Cost) − Indirect Tax (→NNP at Factor Cost, which is National Income).' },
  { id: 'eco-042', category: 'Economics - National Income', question: 'Net National Product (NNP) at Factor Cost is also known as:', options: ['Gross Domestic Product', 'National Income', 'Personal Income', 'Disposable Income'], answer: 1, explanation: 'NNP at Factor Cost is the same as National Income of a country.' },
  { id: 'eco-043', category: 'Economics - National Income', question: 'GNP correctly refers to:', options: ['Income of foreigners in India', 'Income earned by Indians at home and abroad', 'Income of the government only', 'Income from exports only'], answer: 1, explanation: 'GNP = income earned by Indians both within India and abroad. GNP − Indirect Tax − Depreciation = NNP.' },
  { id: 'eco-044', category: 'Economics - National Income', question: 'Which of the following is EXCLUDED while measuring a country\'s GDP?', options: ['Consumer spending on final goods and services', 'Government expenditure on public services', 'Intermediate goods used in production', 'Net exports (Exports − Imports)'], answer: 2, explanation: 'Intermediate goods (raw materials, processing costs) used in production are excluded from GDP to avoid double counting.' },
  { id: 'eco-045', category: 'Economics - National Income', question: 'The sum of Net Investment and Depreciation gives:', options: ['Net National Product', 'Gross Investment', 'National Income', 'Disposable Income'], answer: 1, explanation: 'Gross Investment = Net Investment + Depreciation, following the same logic as Gross = Net + Depreciation.' },
  { id: 'eco-046', category: 'Economics - National Income', question: 'GDP Deflator is calculated using which formula?', options: ['Real GDP / Nominal GDP × 100', 'Nominal GDP / Real GDP × 100', 'Nominal GDP − Real GDP', 'Real GDP + Nominal GDP'], answer: 1, explanation: 'GDP Deflator = (Nominal GDP / Real GDP) × 100. It measures the overall price level of all goods and services produced domestically.' },
  { id: 'eco-047', category: 'Economics - National Income', question: 'GDP = C + I + G + (X − M). What does this equation represent?', options: ['Only private sector spending', 'The expenditure method of calculating GDP', 'The income method of calculating GDP', 'Net Income from Abroad only'], answer: 1, explanation: 'This is the expenditure approach: GDP = Consumption + Investment + Government spending + (Exports − Imports).' },
  { id: 'eco-048', category: 'Economics - National Income', question: 'The total income earned by an individual from all sources before paying personal tax is called:', options: ['Disposable Income', 'Personal Income', 'National Income', 'GNP'], answer: 1, explanation: 'Personal Income is the total income from all sources before personal taxes are paid; after subtracting personal tax, it becomes Disposable Income.' },
  { id: 'eco-049', category: 'Economics - National Income', question: 'Which of the following is NOT a method of estimating National Income?', options: ['Income Method', 'Expenditure Method', 'Matrix Method', 'Product (Value Added) Method'], answer: 2, explanation: 'The three standard methods are Income Method, Expenditure Method and Product/Value Added Method. "Matrix Method" is not used in national income accounting.' },
  { id: 'eco-050', category: 'Economics - National Income', question: 'National Income is basically defined as:', options: ['GDP at Market Price', 'GNP at Market Price', 'NNP at Factor Cost', 'NDP at Market Price'], answer: 2, explanation: 'National Income = NNP at Factor Cost, arrived at after adjusting GDP for depreciation, net income from abroad, and indirect taxes.' },

  // ===================== STATEMENT-BASED: GDP/MACRO =====================
  { id: 'eco-051', category: 'Economics - GDP Statements', question: 'Consider the statements: (1) Treating a single commodity as representative of all goods simplifies aggregate analysis in macroeconomics. (2) All commodities behave identically during inflation. Which is correct?', options: ['Only statement 1 is correct', 'Only statement 2 is correct', 'Both statements are correct', 'Neither statement is correct'], answer: 0, explanation: 'In macroeconomics, using one representative commodity simplifies calculations (statement 1 is true), but not all goods behave the same way during inflation — essentials rise faster than luxury items (statement 2 is false).' },
  { id: 'eco-052', category: 'Economics - GDP Statements', question: 'Consider the statements: (A) GDP does not fully explain how well people in a country are actually living. (R) GDP does not include factors like wear and tear of machines, pollution, or income distribution. Choose the correct option.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], answer: 0, explanation: 'GDP indeed does not capture depreciation of machinery, pollution, or income distribution, which is exactly why it cannot fully reflect people\'s actual quality of life — R correctly explains A.' },
  { id: 'eco-053', category: 'Economics - GDP Statements', question: 'Consider the statements: (1) Real GDP growth rate has been continuously increasing over the last decade. (2) GDP at market prices has been growing steadily over the last decade. Which is correct?', options: ['Only statement 1 is correct', 'Only statement 2 is correct', 'Both are correct', 'Neither is correct'], answer: 1, explanation: 'GDP growth rate has fluctuated (sometimes fallen), so statement 1 is false. However, GDP at market prices has grown steadily due to consistently rising prices, so statement 2 is true.' },

  // ===================== TAX, FIRMS AND MARKET =====================
  { id: 'eco-054', category: 'Economics - Opportunity Cost', question: 'The value of the next best alternative forgone when a choice is made is called:', options: ['Sunk cost', 'Opportunity cost', 'Marginal cost', 'Fixed cost'], answer: 1, explanation: 'Opportunity cost is the value of the next best alternative forgone when a choice is made (e.g., choosing one car model over another).' },
  { id: 'eco-055', category: 'Economics - Distress Sale', question: 'When an asset is sold urgently at a loss or at no profit due to immediate cash requirement, it is called:', options: ['Distress sale', 'Speculative sale', 'Auction sale', 'Forward sale'], answer: 0, explanation: 'A distress sale occurs when an asset (like a house or gold) is sold urgently, often at a loss or without profit, due to a pressing need for cash.' },
  { id: 'eco-056', category: 'Economics - Invisible Hand', question: 'What does the "Invisible Hand" concept given by Adam Smith mean?', options: ['Government control over monopolies', 'Market equilibrium achieved through self-interest without government intervention', 'International trade regulation', 'Central bank control of money supply'], answer: 1, explanation: 'The Invisible Hand concept means buyers and sellers, acting in self-interest, naturally achieve market equilibrium (price adjustment) without government intervention — the core of free-market capitalism, from Adam Smith\'s "The Wealth of Nations".' },
  { id: 'eco-057', category: 'Economics - Market Equilibrium', question: 'The point where the demand curve and supply curve intersect is called:', options: ['Market equilibrium', 'Break-even point', 'Indifference point', 'Elasticity point'], answer: 0, explanation: 'Market equilibrium is the point where demand and supply curves meet, and price adjusts naturally through bargaining between buyers and sellers.' },
  { id: 'eco-058', category: 'Economics - Tax Incidence', question: 'The incidence (burden) of sales tax ultimately falls directly on:', options: ['The Producer', 'The Wholesale Dealer', 'The Retail Dealer', 'The Consumer (end user)'], answer: 3, explanation: 'While tax is passed from producer to wholesaler to retailer, the ultimate burden always falls on the end consumer.' },
  { id: 'eco-059', category: 'Economics - Public Finance Thinkers', question: 'Who first suggested imposing tax on expenditure (an expenditure tax)?', options: ['Dalton', 'Nicholas Kaldor', 'Musgrave', 'Gautam Mathur'], answer: 1, explanation: 'Nicholas Kaldor first proposed the concept of taxing a person\'s expenditure, in addition to income tax.' },

  // ===================== FISCAL & MONETARY POLICY =====================
  { id: 'eco-060', category: 'Economics - Fiscal vs Monetary Policy', question: 'Fiscal policy in India is formulated by:', options: ['Reserve Bank of India', 'Government of India', 'World Bank', 'IMF'], answer: 1, explanation: 'Fiscal Policy (budget terms, expenditure, borrowings) is formulated by the Government of India, whereas Monetary Policy is formulated by the RBI.' },
  { id: 'eco-061', category: 'Economics - Fiscal vs Monetary Policy', question: 'Monetary policy in India is formulated by:', options: ['Ministry of Finance', 'NITI Aayog', 'Reserve Bank of India', 'SEBI'], answer: 2, explanation: 'Monetary Policy, dealing with repo rate, CRR, SLR etc., is formulated by the Reserve Bank of India (RBI) on a quarterly basis.' },
  { id: 'eco-062', category: 'Economics - Fiscal Policy', question: 'Which of the following is NOT a component of Fiscal Policy in India?', options: ['Government receipts', 'Public debt', 'Government expenditure', 'Repo rate'], answer: 3, explanation: 'Repo rate is a tool of Monetary Policy set by the RBI, not a component of Fiscal Policy which deals with budget, expenditure and borrowings.' },
  { id: 'eco-063', category: 'Economics - Fiscal Policy', question: 'Which option best describes the main objective of the government\'s fiscal policy?', options: ['Controlling money supply and interest rates', 'Promoting international trade', 'Influencing aggregate demand and economic activity through government spending and taxation', 'Regulating the stock market'], answer: 2, explanation: 'Fiscal policy influences aggregate demand and economic activity through government spending and taxation, aiming to control demand, reduce unemployment and maintain stability.' },
  { id: 'eco-064', category: 'Economics - Fiscal Policy Types', question: 'When the government increases spending and reduces taxes during a recession to boost demand, output and employment, this is called:', options: ['Contractionary fiscal policy', 'Expansionary fiscal policy', 'Neutral fiscal policy', 'Balanced fiscal policy'], answer: 1, explanation: 'Expansionary fiscal policy is used during recession — government spending increases, taxes decrease, boosting demand, output and employment, though it increases fiscal deficit.' },
  { id: 'eco-065', category: 'Economics - Fiscal Policy Types', question: 'Which of the following is NOT a characteristic of Expansionary Fiscal Policy?', options: ['Decrease in personal taxes', 'Increase in government spending', 'Decrease in government spending', 'Decrease in business taxes'], answer: 2, explanation: 'Expansionary fiscal policy requires increasing (not decreasing) government spending, along with reducing personal and business taxes.' },
  { id: 'eco-066', category: 'Economics - Fiscal Policy Types', question: 'When inflation is high, the government reduces spending and increases taxes to reduce aggregate demand — this is called:', options: ['Expansionary fiscal policy', 'Contractionary fiscal policy', 'Monetary easing', 'Quantitative easing'], answer: 1, explanation: 'Contractionary fiscal policy is used during high inflation — government spending is reduced and taxes are increased to absorb excess money and reduce demand.' },
  { id: 'eco-067', category: 'Economics - FRBM Act', question: 'What is the role of the Finance Minister under the FRBM Act (Fiscal Responsibility and Budget Management Act)?', options: ['To regulate the stock market', 'To oversee disinvestment strategies', 'To manage foreign trade policies', 'To present fiscal policy statements to the Parliament'], answer: 3, explanation: 'Under the FRBM Act, 2003, the Finance Minister is responsible for presenting fiscal policy statements to the Parliament, ensuring fiscal transparency, discipline and accountability.' },

  // ===================== BANKING & MONETARY TOOLS =====================
  { id: 'eco-068', category: 'Economics - Banking Terms', question: 'The rate at which RBI lends money to commercial banks for a short period is called:', options: ['Bank Rate', 'Repo Rate', 'Reverse Repo Rate', 'Cash Reserve Ratio'], answer: 1, explanation: 'Repo Rate is the rate at which RBI lends money to commercial banks for a short term, against government securities as collateral.' },
  { id: 'eco-069', category: 'Economics - Banking Terms', question: 'The rate at which RBI lends money to commercial banks for a longer period is called:', options: ['Repo Rate', 'Bank Rate', 'Reverse Repo Rate', 'MSF'], answer: 1, explanation: 'Bank Rate is the rate at which RBI lends money to banks for a longer term; it is also used to impose penalties for non-compliance with RBI norms.' },
  { id: 'eco-070', category: 'Economics - Banking Terms', question: 'The rate at which RBI borrows money from commercial banks is called:', options: ['Repo Rate', 'Bank Rate', 'Reverse Repo Rate', 'CRR'], answer: 2, explanation: 'Reverse Repo Rate is the interest rate at which RBI borrows money from commercial banks, the opposite of the Repo Rate mechanism.' },
  { id: 'eco-071', category: 'Economics - Banking Terms', question: 'The percentage of bank deposits that banks must keep with RBI in the form of cash is called:', options: ['SLR', 'CRR', 'MSF', 'Repo Rate'], answer: 1, explanation: 'CRR (Cash Reserve Ratio) is the percentage of bank deposits that must be kept with RBI as cash reserves.' },
  { id: 'eco-072', category: 'Economics - Banking Terms', question: 'The percentage of bank deposits that must be maintained in the form of liquid assets like gold and government securities is called:', options: ['CRR', 'SLR', 'Repo Rate', 'MSF'], answer: 1, explanation: 'SLR (Statutory Liquidity Ratio) is the percentage of deposits banks must maintain in liquid assets such as gold or government securities.' },
  { id: 'eco-073', category: 'Economics - Banking Terms', question: 'A facility that allows banks to borrow from RBI at a higher interest rate during emergency situations is called:', options: ['Liquidity Adjustment Facility (LAF)', 'Marginal Standing Facility (MSF)', 'Open Market Operations (OMO)', 'Cash Reserve Ratio (CRR)'], answer: 1, explanation: 'Marginal Standing Facility (MSF) allows banks to borrow from RBI at a higher-than-normal interest rate during emergency/crisis situations.' },
  { id: 'eco-074', category: 'Economics - Banking Terms', question: 'The mechanism under which RBI operates through Repo Rate and Reverse Repo Rate to manage short-term liquidity is called:', options: ['Open Market Operations', 'Liquidity Adjustment Facility (LAF)', 'Marginal Standing Facility', 'Statutory Liquidity Ratio'], answer: 1, explanation: 'The Liquidity Adjustment Facility (LAF) works through the Repo Rate and Reverse Repo Rate mechanism to manage short-term liquidity in the economy.' },
  { id: 'eco-075', category: 'Economics - Banking Terms', question: 'When RBI buys or sells government securities in the open market to control liquidity, this is called:', options: ['Marginal Standing Facility', 'Open Market Operations (OMO)', 'Cash Reserve Ratio', 'Statutory Liquidity Ratio'], answer: 1, explanation: 'Open Market Operations (OMO) refer to RBI buying or selling government securities in the open market to inject or absorb liquidity.' },
  { id: 'eco-076', category: 'Economics - Statements', question: 'Consider the statements: (1) An increase in CRR and SLR requirements increases the lending capacity of banks. (2) These requirements reduce the funds available for banks to lend. Which is correct?', options: ['Only statement 1 is correct', 'Only statement 2 is correct', 'Both are correct', 'Neither is correct'], answer: 1, explanation: 'When CRR/SLR increase, banks have less money to lend, so their lending capacity decreases, not increases. Statement 2 is correct; statement 1 is false.' },
  { id: 'eco-077', category: 'Economics - Money Multiplier', question: 'Which of the following statements about the Money Multiplier is/are correct? (1) Cash held by individuals reduces the money multiplier. (2) Higher reserves held by banks with RBI increase the money multiplier. (3) A higher CRR reduces the banking system\'s capacity to create money.', options: ['Only 1 and 2', 'Only 1 and 3', 'Only 2 and 3', 'All three'], answer: 1, explanation: 'Cash held by public reduces money multiplier (1 is true), banks holding more reserves with RBI does NOT increase money multiplier — it reduces lendable funds (2 is false), and a higher CRR reduces the banking system\'s capacity to create money (3 is true).' },
  { id: 'eco-078', category: 'Economics - Money Types', question: 'Currency that has value because the government declares it legal tender, and is not convertible into gold, is called:', options: ['Representative money', 'Fiat money', 'Commodity money', 'Token money'], answer: 1, explanation: 'Fiat money derives its value from government authority/declaration, not from gold or any commodity backing.' },
  { id: 'eco-079', category: 'Economics - Money Types', question: 'Money issued against collateral, based on trust, such as pledging property for a loan, is called:', options: ['Fiat money', 'Fiduciary money', 'Token money', 'Digital currency'], answer: 1, explanation: 'Fiduciary money is issued against collateral, based on trust, e.g., pledging a property to get a loan.' },
  { id: 'eco-080', category: 'Economics - Money Types', question: 'Money given at face value as a guarantee to lock a deal (such as a token amount for booking a car) is called:', options: ['Token money', 'Representative money', 'Fiduciary money', 'CBDC'], answer: 0, explanation: 'Token money is given at face value to lock in a deal, e.g., paying a token amount to book a property or vehicle.' },
  { id: 'eco-081', category: 'Economics - Money Types', question: 'A digital form of fiat currency issued directly by the RBI is called:', options: ['Token money', 'Cryptocurrency', 'Central Bank Digital Currency (CBDC)', 'Representative money'], answer: 2, explanation: 'CBDC (Central Bank Digital Currency) is the digital form of fiat currency issued directly by the RBI (e.g., the digital rupee).' },
  { id: 'eco-082', category: 'Economics - Currency', question: 'Consider the statements: (1) Unlimited convertibility with fixed price conversion affects currency credibility. (2) International Monetary Systems regulate a country\'s internal fiscal policy. Which is correct?', options: ['Only statement 1', 'Only statement 2', 'Both', 'Neither'], answer: 0, explanation: 'Unlimited convertibility with fixed price conversion does affect currency credibility (statement 1 is true), but International Monetary Systems do not regulate internal fiscal policy — that remains the domain of national governments and central banks (statement 2 is false).' },
  { id: 'eco-083', category: 'Economics - Modern Currency', question: 'Which statement correctly describes the modern currency system after 1971?', options: ['Currencies are fully backed by gold', 'Currencies are not readily convertible into gold', 'Currencies can always be exchanged for oil', 'Currencies are backed by silver'], answer: 1, explanation: 'After the 1971 Nixon Shock, the Gold Standard ended, and modern currencies are fiat money, not readily convertible into gold, silver or oil.' },
  { id: 'eco-084', category: 'Economics - Coinage', question: 'Why does the Government of India (not RBI) print the ₹1 coin/note?', options: ['Because RBI has no legal authority to print money', 'Because the ₹1 coin comes under the Coinage Act while RBI notes come under the RBI Act, and it guarantees the Rupee\'s validity', 'Because ₹1 coins are made of a different metal', 'Because it is a tradition with no legal reason'], answer: 1, explanation: 'The ₹1 note/coin is issued under the Coinage Act by the Government of India (signed by the Finance Secretary), guaranteeing that RBI (an undertaking of the government) issued currency is valid, whereas RBI issues other denominations under the RBI Act.' },
  { id: 'eco-085', category: 'Economics - FEMA', question: 'FERA (Foreign Exchange Regulation Act) in India was replaced by:', options: ['SEBI Act', 'FEMA (Foreign Exchange Management Act)', 'Companies Act', 'Banking Regulation Act'], answer: 1, explanation: 'FERA (1973), which had strict criminal penalties, was replaced by FEMA (Foreign Exchange Management Act, applied in 2000), which has milder civil penalties.' },
  { id: 'eco-086', category: 'Economics - FEMA', question: 'Under FEMA, what is the maximum limit for foreign exchange remittance allowed per financial year under the Liberalised Remittance Scheme?', options: ['$1 lakh', '$1.5 lakh', '$2.5 lakh', '$5 lakh'], answer: 2, explanation: 'Under FEMA, an individual can remit a maximum of $2.5 lakh per financial year under the Liberalised Remittance Scheme (LRS).' },

  // ===================== INFLATION =====================
  { id: 'eco-087', category: 'Economics - Inflation Types', question: 'Inflation caused by demand exceeding supply (e.g., iPhones with high demand but limited supply) is called:', options: ['Cost-push inflation', 'Demand-pull inflation', 'Built-in inflation', 'Stagflation'], answer: 1, explanation: 'Demand-pull inflation occurs when demand exceeds supply, e.g., high demand for new iPhone models exceeding available stock.' },
  { id: 'eco-088', category: 'Economics - Inflation Types', question: 'Inflation caused by a rise in production costs (e.g., restriction on cutting trees raising the cost of Kashmir Willow bats) is called:', options: ['Demand-pull inflation', 'Cost-push inflation', 'Hyperinflation', 'Disinflation'], answer: 1, explanation: 'Cost-push inflation arises from an increase in production cost, which sellers pass on as higher prices.' },
  { id: 'eco-089', category: 'Economics - Inflation Types', question: 'Inflation caused by a wage-price spiral, where higher wages lead to higher costs and prices, is called:', options: ['Built-in inflation', 'Demand-pull inflation', 'Stagflation', 'Deflation'], answer: 0, explanation: 'Built-in inflation is caused due to the wage-price spiral, where higher wages for workers push up production costs and prices.' },
  { id: 'eco-090', category: 'Economics - Inflation Types', question: 'A sudden and extreme rise in prices (e.g., gold prices jumping by ₹800-1000 suddenly) is called:', options: ['Disinflation', 'Deflation', 'Hyperinflation', 'Stagflation'], answer: 2, explanation: 'Hyperinflation refers to a sudden, extreme and uncontrolled rise in prices.' },
  { id: 'eco-091', category: 'Economics - Inflation Types', question: 'The economic phenomenon where high inflation is combined with stagnant economic growth is called:', options: ['Deflation', 'Disinflation', 'Stagflation', 'Reflation'], answer: 2, explanation: 'Stagflation refers to high inflation combined with stagnant/stalled economic growth, often caused by supply shocks or poor policy decisions.' },
  { id: 'eco-092', category: 'Economics - Inflation Types', question: 'A general decline in price levels is called:', options: ['Disinflation', 'Deflation', 'Stagflation', 'Hyperinflation'], answer: 1, explanation: 'Deflation refers to a fall in the general price level, the opposite of inflation.' },
  { id: 'eco-093', category: 'Economics - Inflation Types', question: 'A slowdown in the rate of inflation (prices still rising but more slowly) is called:', options: ['Deflation', 'Disinflation', 'Stagflation', 'Hyperinflation'], answer: 1, explanation: 'Disinflation refers to a fall in the rate of inflation — prices are still rising, but at a slower pace than before.' },
  { id: 'eco-094', category: 'Economics - Inflation', question: 'Which type of inflation excludes food and fuel prices from its measurement?', options: ['Headline inflation', 'Core inflation', 'Hyperinflation', 'Stagflation'], answer: 1, explanation: 'Core inflation excludes volatile food and fuel prices, whereas Headline inflation includes food and fuel as well.' },
  { id: 'eco-095', category: 'Economics - Inflation & Distribution', question: 'When there is high inflation in the market, income and wealth are generally redistributed in favour of:', options: ['Pensioners', 'The poor', 'The business/rich class', 'Middle class'], answer: 2, explanation: 'During inflation, the business/rich class benefits the most since the value of their land, property and products rises, while pensioners and the poor lose purchasing power.' },
  { id: 'eco-096', category: 'Economics - Inflation Impact', question: 'Between debtors and creditors, who suffers the most during high inflation (when the RBI raises interest rates)?', options: ['Debtors', 'Creditors', 'Both benefit equally', 'Neither is affected'], answer: 1, explanation: 'Creditors (those who have lent money, e.g., taken a floating-rate loan) suffer during inflation because rising interest rates increase their repayment burden (EMI).' },

  // ===================== FDI, TRADE, WTO =====================
  { id: 'eco-097', category: 'Economics - FDI', question: 'A higher international interest rate will generally have what impact on FDI (Foreign Direct Investment)?', options: ['FDI increases', 'FDI decreases', 'No impact on FDI', 'FDI becomes zero'], answer: 1, explanation: 'A higher interest rate reduces the profit margin for foreign investors, discouraging investment, thereby decreasing FDI inflows.' },
  { id: 'eco-098', category: 'Economics - Trade', question: 'The exchange of commodities between two countries, done to build good trade relations rather than for necessity, is called:', options: ['Balance of Trade', 'Bilateral Trade', 'Volume of Trade', 'Multilateral Trade'], answer: 2, explanation: 'Volume of Trade refers to the exchange of commodities between two countries mainly to build/strengthen relations, e.g., exchanging tulips and apples.' },
  { id: 'eco-099', category: 'Economics - WTO', question: 'The World Trade Organisation (WTO), established in 1995, mainly promotes:', options: ['Financial support to poor nations', 'Unilateral trade', 'Multilateral trade among all nations', 'Bilateral aid programmes'], answer: 2, explanation: 'The WTO promotes multilateral trade — where all member countries are interconnected and can trade freely with one another.' },
  { id: 'eco-100', category: 'Economics - Foreign Trade', question: 'Consider the statements about foreign trade\'s impact on Aggregate Demand (AD) in India: (1) Imports act as a leakage, reducing AD. (2) Exports act as an injection, increasing AD. Which is correct?', options: ['Only statement 1', 'Only statement 2', 'Both statements are correct', 'Neither statement is correct'], answer: 2, explanation: 'Imports are a leakage that reduces aggregate demand, while exports are an injection that increases aggregate demand — both statements are correct.' },
  { id: 'eco-101', category: 'Economics - Terms of Credit', question: 'Which of the following is NOT a component of the "Terms of Credit"?', options: ['Collateral', 'Interest Rate', 'Documentation', 'Source of Credit'], answer: 3, explanation: 'Terms of Credit includes interest rate, collateral, documentation and repayment mode — but the "source of credit" (where the bank got the money) is not disclosed to the borrower and is not a term of credit.' },

  // ===================== BUDGET =====================
  { id: 'eco-102', category: 'Economics - Budget Types', question: 'A budget where the estimated expenditure and actual expenditure remain equal (used mostly by developed countries) is called:', options: ['Unbalanced budget', 'Balanced budget', 'Deficit budget', 'Surplus budget'], answer: 1, explanation: 'A Balanced Budget is one where estimated expenditure equals actual expenditure; developed countries like the US, UK and France usually follow this.' },
  { id: 'eco-103', category: 'Economics - Budget Types', question: 'A budget where actual expenditure exceeds the estimated amount (typical of developing countries like India) is called:', options: ['Balanced budget', 'Unbalanced budget', 'Gender budget', 'Outcome budget'], answer: 1, explanation: 'An Unbalanced budget is one where actual expenditure exceeds the estimate; developing countries such as India and China typically follow this pattern.' },
  { id: 'eco-104', category: 'Economics - Budget Types', question: 'A budget where income exceeds expenditure is called a:', options: ['Deficit budget', 'Surplus budget', 'Balanced budget', 'Zero-based budget'], answer: 1, explanation: 'A Surplus Budget is one where income is more than expenditure, i.e., there is savings.' },
  { id: 'eco-105', category: 'Economics - Budget Types', question: 'A budget where expenditure exceeds income, requiring borrowing to cover the gap, is called a:', options: ['Surplus budget', 'Deficit budget', 'Balanced budget', 'Gender budget'], answer: 1, explanation: 'A Deficit (Ghata) Budget is one where expenditure exceeds income, requiring the government to borrow to bridge the gap.' },
  { id: 'eco-106', category: 'Economics - Budget Types', question: 'The budgeting system where the previous year\'s allocation is simply carried forward (used in India until around 1980) is called:', options: ['Zero-based budgeting', 'Performance-based budgeting', 'Outcome budgeting', 'Gender budgeting'], answer: 1, explanation: 'Performance-based budgeting simply repeats/rolls forward previous allocations without a fresh review; India used this until around 1980.' },
  { id: 'eco-107', category: 'Economics - Zero-Based Budgeting', question: 'What is the primary goal of Zero-Based Budgeting?', options: ['To track only past expenses', 'To increase tax revenue', 'To link revenue with exports', 'To justify all expenditures from scratch each year'], answer: 3, explanation: 'Zero-Based Budgeting requires every ministry/department to justify all its expenditures afresh, from zero, each year, rather than simply carrying forward previous allocations.' },
  { id: 'eco-108', category: 'Economics - Budget Types', question: 'A budget that reviews certain schemes every 90 days and increases allocations based on their performance is called:', options: ['Outcome budget', 'Gender budget', 'Performance budget', 'Zero-based budget'], answer: 0, explanation: 'An Outcome Budget reviews schemes periodically (e.g., every 3 months) and adjusts fund allocation based on outcomes achieved (e.g., Namami Gange project).' },
  { id: 'eco-109', category: 'Economics - Budget Types', question: 'A part of the Union Budget allocated specifically for women\'s welfare schemes is called:', options: ['Gender-based budget', 'Green budget', 'Outcome budget', 'Zero-based budget'], answer: 0, explanation: 'Gender Budget refers to the portion of the annual budget specifically allocated for the welfare of women, such as women\'s safety schemes or widow pension schemes.' },
  { id: 'eco-110', category: 'Economics - Green Budget', question: 'Consider the statements about the "Green Budget": (1) It adds a green (environmental) component to the budget. (2) It plays an important role in conserving natural resources for future generations. (3) It is a new concept introduced in 2018-19. Which is correct?', options: ['Only 1 and 2 are correct', 'Only 2 and 3 are correct', 'All three are correct', 'Only 1 is correct'], answer: 0, explanation: 'The Green Budget adds an environmental component to the budget (1 is true) and helps conserve resources for future generations (2 is true), but it was introduced around 2020, not 2018-19 (3 is false).' },
  { id: 'eco-111', category: 'Economics - Fiscal Deficit', question: 'Another term used for Budgetary Deficit is:', options: ['Revenue Deficit', 'Fiscal Deficit', 'Primary Deficit', 'Trade Deficit'], answer: 1, explanation: 'Budgetary Deficit is also known as Fiscal Deficit = Total Expenditure − Total Receipts (excluding borrowings).' },
  { id: 'eco-112', category: 'Economics - Deficit Definitions', question: 'Primary Deficit is calculated as:', options: ['Fiscal Deficit + Interest Payments', 'Fiscal Deficit − Interest Payments', 'Revenue Deficit − Interest Payments', 'Total Expenditure − Total Receipts'], answer: 1, explanation: 'Primary Deficit = Fiscal Deficit − Interest Payments.' },
  { id: 'eco-113', category: 'Economics - Revenue Receipts', question: 'Consider the statements: (A) Government revenue receipts do not carry any burden of repayment or financial liability. (R) Revenue receipts are not returned and generally come from tax or other regular income sources. Choose the correct option.', options: ['Both A and R are true and R correctly explains A', 'Both A and R are true but R does not explain A', 'A is true, R is false', 'A is false, R is true'], answer: 0, explanation: 'Revenue receipts (like tax income) do not need to be repaid and come from regular sources — this is exactly why they do not carry a repayment burden, making R the correct explanation of A.' },
  { id: 'eco-114', category: 'Economics - Disinvestment', question: 'Consider the statements: (1) Disinvestment policy has been widely criticised in India. (2) Disinvestment results in increased monopoly of Public Sector Undertakings (PSUs). Which is correct?', options: ['Only statement 1 is correct', 'Only statement 2 is correct', 'Both are correct', 'Neither is correct'], answer: 0, explanation: 'Disinvestment has indeed been widely criticised in India (statement 1 true), but it reduces (not increases) the monopoly of PSUs since it transfers ownership to the private sector (statement 2 is false).' },
  { id: 'eco-115', category: 'Economics - Disinvestment', question: 'When the government sells less than 50% of its stake in a Public Sector Undertaking while retaining control, this type of sale is called:', options: ['Complete sale', 'Majority sale', 'Minority sale', 'Strategic sale'], answer: 2, explanation: 'A Minority Sale is when the government sells less than 50% of its stake in a PSU while retaining control and inviting private participation, commonly used in disinvestment programmes.' },

  // ===================== PSU CLASSIFICATION =====================
  { id: 'eco-116', category: 'Economics - PSU Classification', question: 'As of 2024, which of the following is NOT a Maharatna company?', options: ['Steel Authority of India Limited (SAIL)', 'Oil and Natural Gas Corporation (ONGC)', 'NTPC Limited', 'Hindustan Copper Limited'], answer: 3, explanation: 'Hindustan Copper Limited is a Miniratna company, not a Maharatna company. SAIL, ONGC and NTPC are all Maharatna companies.' },
  { id: 'eco-117', category: 'Economics - PSU Classification', question: 'How much can a Maharatna PSU invest without seeking prior government approval?', options: ['₹300 crore', '₹1000 crore', '₹5000 crore', '₹500 crore'], answer: 2, explanation: 'A Maharatna company can invest up to ₹5000 crore without seeking prior approval from the Government of India.' },
  { id: 'eco-118', category: 'Economics - PSU Classification', question: 'How much can a Navratna PSU invest without government approval?', options: ['₹300 crore', '₹500 crore', '₹1000 crore', '₹5000 crore'], answer: 2, explanation: 'A Navratna company can invest up to ₹1000 crore without needing government approval.' },
  { id: 'eco-119', category: 'Economics - PSU Classification', question: 'To become a Maharatna, a company must have been continuously profitable for the last three years and must already be classified as:', options: ['Miniratna for 3 years', 'Navratna for 3 years', 'A private company for 3 years', 'A listed company for 3 years'], answer: 1, explanation: 'A company becomes a Maharatna only if it has been continuously profitable for 3 years and has already held Navratna status for the preceding 3 years.' },

  // ===================== SCARCITY, EFFECTS, SNOB/BANDWAGON =====================
  { id: 'eco-120', category: 'Economics - Definitions', question: 'The Scarcity Definition of Economics (that human wants are unlimited but resources are limited, requiring choice) was given by:', options: ['Adam Smith', 'Lionel Robbins', 'John Maynard Keynes', 'Alfred Marshall'], answer: 1, explanation: 'Lionel Robbins gave the Scarcity Definition of Economics in his 1932 book, moving the study of economics from wealth/welfare to the science of choice-making.' },
  { id: 'eco-121', category: 'Economics - Consumer Behaviour', question: 'When the demand for a commodity decreases because many other people are also consuming it (loss of exclusivity), this effect is called:', options: ['Bandwagon effect', 'Snob effect', 'Veblen effect', 'Substitution effect'], answer: 1, explanation: 'The Snob effect occurs when higher-income groups avoid goods that become too common/popular, valuing exclusivity/status over the item itself (e.g., elite class shifting from Rolex to Hublot).' },
  { id: 'eco-122', category: 'Economics - Consumer Behaviour', question: 'When demand for a product increases because more and more people are buying it (people follow the crowd), this effect is called:', options: ['Snob effect', 'Bandwagon effect', 'Giffen effect', 'Income effect'], answer: 1, explanation: 'The Bandwagon effect is the opposite of the snob effect — people buy a product because they see others buying it too.' },

  // ===================== EMPLOYMENT & LABOUR =====================
  { id: 'eco-123', category: 'Economics - Employment Indicators', question: 'Which indicator is used for analysing occupational structure and unemployment in India?', options: ['Sex Ratio', 'Labour Force Participation Rate (LFPR)', 'Literacy Rate', 'Per Capita Income'], answer: 1, explanation: 'LFPR (Labour Force Participation Rate) measures the proportion of the working-age population that is employed or actively seeking work, directly reflecting occupational structure and unemployment.' },
  { id: 'eco-124', category: 'Economics - Poverty Line', question: 'As per the 2011-12 National Poverty Line estimate, what was the per capita monthly expenditure threshold for Rural India?', options: ['₹1000', '₹816', '₹972', '₹1407'], answer: 1, explanation: 'As per the 2011-12 poverty line (Tendulkar methodology), the rural poverty threshold was ₹816 per capita per month, while the urban threshold was ₹1000.' },
  { id: 'eco-125', category: 'Economics - Unemployment Statements', question: 'Consider the statements: (1) Seasonal unemployment is mainly found in urban areas. (2) Educated unemployment is mainly found in rural areas of India. (3) Multiple cropping is considered a good way to reduce unemployment in the rural economy. Which is/are correct?', options: ['Only statement 3', 'Only statements 1 and 2', 'All three', 'None of the statements'], answer: 0, explanation: 'Seasonal unemployment is not confined to urban areas (statement 1 is false); educated unemployment is mainly found in urban, not rural, areas (statement 2 is false); multiple cropping is indeed a good way to reduce disguised/seasonal unemployment in rural areas (statement 3 is true).' },
  { id: 'eco-126', category: 'Economics - Unemployment Types', question: 'Unemployment caused when technology/skill requirements change and workers cannot adapt (mismatch of skills) is called:', options: ['Frictional unemployment', 'Structural unemployment', 'Cyclical unemployment', 'Seasonal unemployment'], answer: 1, explanation: 'Structural unemployment occurs due to a mismatch between workers\' skills and job requirements, often caused by technological/economic change.' },
  { id: 'eco-127', category: 'Economics - Unemployment Types', question: 'Short-term unemployment that occurs while a person is searching for a new job or switching jobs is called:', options: ['Structural unemployment', 'Frictional unemployment', 'Cyclical unemployment', 'Disguised unemployment'], answer: 1, explanation: 'Frictional unemployment refers to short-term unemployment during the period of searching for or switching to a new job.' },
  { id: 'eco-128', category: 'Economics - Unemployment Types', question: 'Unemployment caused by economic recession, following the business cycle, is called:', options: ['Frictional unemployment', 'Structural unemployment', 'Cyclical unemployment', 'Casual unemployment'], answer: 2, explanation: 'Cyclical unemployment arises due to economic recession/depression and follows the boom-bust business cycle; it declines as the economy recovers.' },
  { id: 'eco-129', category: 'Economics - Unemployment Types', question: 'Unemployment where educated individuals are unable to find suitable jobs, usually in urban areas, is called:', options: ['Educated unemployment', 'Casual unemployment', 'Technological unemployment', 'Disguised unemployment'], answer: 0, explanation: 'Educated unemployment refers to educated persons being unable to find suitable jobs despite having degrees, mostly found in urban areas.' },
  { id: 'eco-130', category: 'Economics - Unemployment Types', question: 'Unemployment caused when machines replace human workers is called:', options: ['Structural unemployment', 'Technological unemployment', 'Frictional unemployment', 'Cyclical unemployment'], answer: 1, explanation: 'Technological unemployment occurs when machines/automation replace human workers in factories and industries.' },
  { id: 'eco-131', category: 'Economics - Unemployment Types', question: 'Unemployment where daily-wage labourers are unable to find regular work is called:', options: ['Casual unemployment', 'Structural unemployment', 'Cyclical unemployment', 'Educated unemployment'], answer: 0, explanation: 'Casual unemployment refers to daily-wage labourers (e.g., at a labour chowk) who are unable to find regular work each day.' },

  // ===================== LORENZ CURVE, HINDU GROWTH RATE =====================
  { id: 'eco-132', category: 'Economics - Income Distribution', question: 'The Lorenz Curve is used to represent:', options: ['Inflation', 'Unemployment', 'Income distribution/inequality', 'Poverty rate directly'], answer: 2, explanation: 'The Lorenz Curve is used along with the Gini Coefficient to show income distribution and measure inequality in an economy.' },
  { id: 'eco-133', category: 'Economics - Hindu Rate of Growth', question: 'Who introduced the term "Hindu Rate of Growth" to describe India\'s slow GDP growth (around 3.5%) before the 1991 reforms?', options: ['Amartya Sen', 'Raj Krishna', 'V.K.R.V. Rao', 'Manmohan Singh'], answer: 1, explanation: 'The term "Hindu Rate of Growth" was coined by economist Raj Krishna in 1978-79 to describe India\'s slow GDP growth of around 3.5% before the 1991 reforms.' },
  { id: 'eco-134', category: 'Economics - HDI', question: 'The Human Development Index (HDI) was first developed by:', options: ['Amartya Sen', 'Mahbub ul Haq', 'Lionel Robbins', 'Simon Kuznets'], answer: 1, explanation: 'Mahbub ul Haq, a Pakistani economist, developed the Human Development Index (HDI).' },
  { id: 'eco-135', category: 'Economics - Nobel Laureates', question: 'In which year was Amartya Sen awarded the Nobel Prize in Economics?', options: ['1990', '1995', '1998', '2001'], answer: 2, explanation: 'Amartya Sen was awarded the Nobel Prize in Economics in 1998.' },
  { id: 'eco-136', category: 'Economics - Father of Economics', question: 'Who is known as the "Father of Economics"?', options: ['John Maynard Keynes', 'Adam Smith', 'Alfred Marshall', 'Lionel Robbins'], answer: 1, explanation: 'Adam Smith is regarded as the Father of Economics, having given the earliest foundational concepts of the discipline.' },
  { id: 'eco-137', category: 'Economics - Father of Macroeconomics', question: 'Who is regarded as the Father of Macroeconomics, having given the concept of "General Theory of Employment, Interest and Money" (1936)?', options: ['Adam Smith', 'Alfred Marshall', 'John Maynard Keynes', 'Amartya Sen'], answer: 2, explanation: 'John Maynard Keynes is the Father of Macroeconomics; he gave the "General Theory of Employment, Interest and Money" in 1936.' },
  { id: 'eco-138', category: 'Economics - Father of Indian Economics', question: 'Who is considered the Father of Indian Economics (associated with the 1991 reforms)?', options: ['Dr. Manmohan Singh', 'V.K.R.V. Rao', 'Dadabhai Naoroji', 'Jawaharlal Nehru'], answer: 0, explanation: 'Dr. Manmohan Singh, who steered India out of the 1991 BOP crisis through LPG reforms, is regarded as the Father of Indian Economics.' },

  // ===================== GLOBALIZATION, DEVELOPMENT =====================
  { id: 'eco-139', category: 'Economics - Globalisation', question: 'In economic terms, Globalisation is essentially the process of rapid ________ between countries.', options: ['Competition', 'Investment', 'Integration', 'Taxation'], answer: 2, explanation: 'Globalisation is essentially the process of rapid integration between countries — enabled by technology, allowing worldwide connectivity in trade and communication.' },
  { id: 'eco-140', category: 'Economics - Economic Development', question: 'Economic development of a country depends on which of the following factors?', options: ['Only natural resources', 'Only capital formation', 'Only size of the market', 'Natural resources, capital formation and size of the market — all of these'], answer: 3, explanation: 'Economic development depends on all these factors together — natural resources, capital formation, and market size all support and drive economic growth.' },
  { id: 'eco-141', category: 'Economics - Literacy', question: 'As per Census 2011, what was India\'s literacy rate?', options: ['66%', '74.04%', '79%', '77%'], answer: 1, explanation: 'As per Census 2011, India\'s literacy rate was 74.04%.' },
  { id: 'eco-142', category: 'Economics - Rural-Urban Gap', question: 'Consider the statements on why rural income in India is generally lower than urban income: (1) A large number of farmers are illiterate with little knowledge of scientific farming. (2) Primary products have lower value than manufactured products. (3) Investment in agriculture has declined compared to investment in industries. Which are correct?', options: ['Only statement 1', 'Only statements 1 and 2', 'Only statements 2 and 3', 'All three statements'], answer: 3, explanation: 'All three factors — illiteracy limiting scientific farming, lower value of primary products compared to manufactured goods, and declining investment in agriculture relative to industry — are valid reasons for the rural-urban income gap.' },
  { id: 'eco-143', category: 'Economics - Sector Contribution', question: 'What is the correct descending order of sectoral contribution to India\'s GDP?', options: ['Agriculture > Industry > Services', 'Industry > Services > Agriculture', 'Services > Industry > Agriculture', 'Services > Agriculture > Industry'], answer: 2, explanation: 'The correct descending order of GDP contribution is Services (Tertiary) > Industry (Secondary) > Agriculture (Primary), with services contributing over 50% of GDP.' },
  { id: 'eco-144', category: 'Economics - Per Capita Income', question: 'Which of the following are among the main reasons for the slow growth of per capita income in India?', options: ['High rate of population growth and high fiscal deficit levels', 'Low rate of capital formation only', 'High literacy rates', 'None of the above'], answer: 0, explanation: 'High population growth rate and (when at a high level) high fiscal deficit are among the main reasons contributing to the slow growth of per capita income in India; a high rate of capital formation (not low) also plays a role when it creates inequality.' },

  // ===================== FIVE YEAR PLANS & POLICY HISTORY =====================
  { id: 'eco-145', category: 'Economics - License Raj', question: 'The regulatory framework followed by India between 1947 and 1990, requiring licenses to conduct most economic activities, was known as:', options: ['Permit Raj only', 'License Raj', 'Command Economy Framework', 'FERA Regime'], answer: 1, explanation: 'From 1947-1990, India followed the "License Raj" system, under which licenses were required for most economic/industrial activities.' },
  { id: 'eco-146', category: 'Economics - License Raj', question: 'Which of the following was a major unintended NEGATIVE consequence of the License Raj (1947-1990)?', options: ['Extremely competitive market environment', 'Rapid rise in global competitiveness of Indian products', 'Significant reduction in corruption and administrative delays', 'Entry barriers for new businesses, leading to reduced innovation and inefficiencies'], answer: 3, explanation: 'The License Raj created major entry barriers for new/private businesses, leading to reduced innovation, inefficiencies, delays and increased corruption — not a reduction in it.' },
  { id: 'eco-147', category: 'Economics - IPR', question: 'India\'s first Industrial Policy was introduced in which year?', options: ['1947', '1948', '1951', '1956'], answer: 1, explanation: 'India\'s first Industrial Policy Resolution (IPR) was introduced in 1948, focused mainly on promoting the public sector.' },
  { id: 'eco-148', category: 'Economics - IPR 1956', question: 'Consider the statements about the Industrial Policy Resolution (IPR) 1956: (A) It created an industrial classification into Schedules A, B and C. (R) The purpose was to identify sectors for exclusive state control, joint sector, and private sector operations. Choose the correct option.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R does not explain A', 'A is true, R is false', 'A is false, R is true'], answer: 0, explanation: 'The IPR 1956 did classify industries into Schedule A (exclusive state control, e.g. defence), Schedule B (joint sector, e.g. PSUs like Coal India), and Schedule C (private sector) — R correctly explains why the classification (A) was created.' },
  { id: 'eco-149', category: 'Economics - Five Year Plans', question: 'The concept of Five Year Plans in India was introduced based on the ideas/model of which economist?', options: ['V.K.R.V. Rao', 'P.C. Mahalanobis', 'Amartya Sen', 'Dadabhai Naoroji'], answer: 1, explanation: 'The Five Year Plans in India were introduced based on the model advised by P.C. Mahalanobis to Nehru\'s government.' },
  { id: 'eco-150', category: 'Economics - First Five Year Plan', question: 'What was the main focus of India\'s First Five Year Plan (1951-1956)?', options: ['Heavy industries', 'Agriculture (based on the Harrod-Domar model)', 'Liberalisation and globalisation', 'Small and cottage industries'], answer: 1, explanation: 'The First Five Year Plan (1951-56) focused on agriculture, using the Harrod-Domar model, prioritising irrigation, land reforms and rural development (e.g., Bhakra Nangal Dam).' },
  { id: 'eco-151', category: 'Economics - Second Five Year Plan', question: 'Which three foreign countries helped India set up heavy industries (steel plants) during the Second Five Year Plan (1956-61)?', options: ['USA, Japan and China', 'Soviet Union (Russia), Britain and Germany', 'France, Canada and Australia', 'New Zealand, France and Japan'], answer: 1, explanation: 'During the Second Five Year Plan, the Soviet Union helped build Bhilai Steel Plant, Britain helped build Durgapur Steel Plant, and Germany helped build Rourkela Steel Plant.' },
  { id: 'eco-152', category: 'Economics - Third Five Year Plan', question: 'Why did India\'s Third Five Year Plan (1961-66) fail?', options: ['Due to excessive economic growth', 'Due to the Indo-China War (1962), Indo-Pak War (1965), drought and rupee devaluation', 'Due to too much foreign investment', 'Due to overproduction of food grains'], answer: 1, explanation: 'The Third Plan failed mainly due to the Indo-China War (1962), the Indo-Pak War (1965), severe drought/food crisis, and devaluation of the rupee.' },
  { id: 'eco-153', category: 'Economics - Plan Holiday', question: 'The period 1966-69, when India took a break from the traditional Five Year Plan system due to the failure of the Third Plan, is known as:', options: ['Rolling Plan period', 'Plan Holiday', 'Annual Plan period', 'Zero Plan period'], answer: 1, explanation: 'The period 1966-69 is known as the "Plan Holiday", when regular Five Year Plans were paused due to the failure of the Third Plan (wars, drought, food crisis).' },
  { id: 'eco-154', category: 'Economics - MRTP Act', question: 'The MRTP Act (Monopolies and Restrictive Trade Practices Act) was introduced during which Five Year Plan?', options: ['Third Five Year Plan', 'Fourth Five Year Plan', 'Fifth Five Year Plan', 'Sixth Five Year Plan'], answer: 1, explanation: 'The MRTP Act, 1969, was introduced during the Fourth Five Year Plan to prevent monopolies and protect consumers; it was later replaced by the Competition Act, 2002.' },
  { id: 'eco-155', category: 'Economics - Green Revolution', question: 'During which Five Year Plan was the Green Revolution launched in India?', options: ['First Five Year Plan', 'Second Five Year Plan', 'Third Five Year Plan', 'Fourth Five Year Plan'], answer: 2, explanation: 'The Green Revolution was launched during the Third Five Year Plan, even though many mistakenly believe it was during the First (which focused on agriculture generally, not the Green Revolution specifically).' },
  { id: 'eco-156', category: 'Economics - Green Revolution', question: 'Who is known as the "Father of the Green Revolution" in India?', options: ['V.K.R.V. Rao', 'M.S. Swaminathan', 'Norman Borlaug', 'P.C. Mahalanobis'], answer: 1, explanation: 'M.S. Swaminathan is regarded as the Father of the Green Revolution in India.' },
  { id: 'eco-157', category: 'Economics - 20 Point Programme', question: 'The "20 Point Programme" launched in 1975 to address rural poverty in India was launched by which Prime Minister?', options: ['Jawaharlal Nehru', 'Indira Gandhi', 'Morarji Desai', 'Rajiv Gandhi'], answer: 1, explanation: 'The 20 Point Programme was launched in 1975 by Prime Minister Indira Gandhi during the Fifth Five Year Plan, aimed at rural development, poverty alleviation and employment.' , notes: ["1971 → Garibi Hatao\n1975 → Twenty Point Programme\n1975–77 → Emergency"],},
  { id: 'eco-158', category: 'Economics - IDBI', question: 'Which institution played a key role in financing industrial projects during the Fifth Five Year Plan (1974-78)?', options: ['RBI', 'IDBI (Industrial Development Bank of India)', 'SBI', 'EXIM Bank'], answer: 1, explanation: 'IDBI (Industrial Development Bank of India), a subsidiary of LIC established in 1964, played a key role in financing industrial projects during the Fifth Plan; it was later converted into a bank in 2004.' },
  { id: 'eco-159', category: 'Economics - Rolling Plan', question: 'The concept of the "Rolling Plan" (with annual targets instead of five-year targets) was introduced during whose Prime Ministership?', options: ['Indira Gandhi', 'Morarji Desai', 'Rajiv Gandhi', 'Charan Singh'], answer: 1, explanation: 'The Rolling Plan concept was introduced by Prime Minister Morarji Desai (Janata Party government) in 1978, replacing the Five Year Plan with annual reviewable targets.' },
  { id: 'eco-160', category: 'Economics - Seventh Five Year Plan', question: 'The Seventh Five Year Plan (1985-90), associated with Rajiv Gandhi, gave major attention to which sector for generating more employment?', options: ['Heavy industries', 'IT sector', 'Small and cottage industries', 'Oil and gas sector'], answer: 2, explanation: 'The Seventh Five Year Plan gave major attention to small and cottage industries to generate employment, support rural economy, and promote self-reliance.' },
  { id: 'eco-161', category: 'Economics - Import Substitution', question: 'What was the main rationale behind the policy of Import Substitution during the first seven Five Year Plans?', options: ['To expand international trade', 'To attract foreign investors', 'To protect newly established domestic industries from foreign competition', 'To build export dependency'], answer: 2, explanation: 'The Import Substitution policy aimed to protect newly established (infant) domestic industries from foreign competition by using higher import duties and quotas.' },
  { id: 'eco-162', category: 'Economics - 1991 Reforms', question: 'Consider the statements: (1) The 1991 reforms opened the Indian economy to foreign investors. (2) The government mainly wanted to rapidly increase the domestic savings rate. Which is correct?', options: ['Only statement 1', 'Only statement 2', 'Both', 'Neither'], answer: 0, explanation: 'The 1991 reforms did open the Indian economy for foreign investors (statement 1 is true), but the reforms were primarily driven by the Balance of Payments (BOP) crisis, not by a goal of rapidly increasing domestic savings (statement 2 is false).' , notes: ["Foreign Investment ↑ ✅\nTrade barriers ↓ ✅\nLicensing ↓ ✅\nPrivate sector role ↑ ✅\nGlobal integration ↑ ✅"],},
  { id: 'eco-163', category: 'Economics - BOP Crisis', question: 'The Balance of Payments (BOP) crisis of 1991 was primarily caused due to a severe shortage of:', options: ['Food grains', 'Labour', 'Foreign exchange reserves', 'Domestic currency'], answer: 2, explanation: 'The 1991 BOP crisis was caused by a severe shortage of foreign exchange reserves, leaving India with barely three weeks of import cover, forcing gold to be pledged with the IMF.' },
  { id: 'eco-164', category: 'Economics - LPG Reforms', question: 'What does "LPG" stand for in the context of India\'s 1991 economic reforms?', options: ['Liquid Petroleum Gas', 'Liberalisation, Privatisation, Globalisation', 'Loan, Payment, Growth', 'License, Permit, Grant'], answer: 1, explanation: 'In the economic context, LPG stands for Liberalisation, Privatisation and Globalisation, the three pillars of India\'s 1991 economic reforms.' },
  { id: 'eco-165', category: 'Economics - Stabilisation Measures', question: 'What was the primary short-term objective of the "Stabilisation" measures under the 1991 reforms?', options: ['Increasing agricultural productivity', 'Increasing spending on social sectors', 'Controlling inflation and correcting the Balance of Payments', 'Privatising public sector units'], answer: 2, explanation: 'Stabilisation measures were short-term steps aimed at controlling inflation and correcting the Balance of Payments, as conditions imposed by the IMF for providing assistance.' },
  { id: 'eco-166', category: 'Economics - Rupee Devaluation', question: 'Why did the Government of India devalue the Rupee during the 1991 BOP crisis?', options: ['To increase imports', 'To reduce exports', 'To gain more foreign exchange assistance by showing genuine economic hardship', 'It was not devalued'], answer: 2, explanation: 'The government devalued the Rupee to convince international institutions (like the IMF) of India\'s genuine economic hardship, in order to receive greater foreign exchange assistance.' },
  { id: 'eco-167', category: 'Economics - Bank Nationalisation', question: 'In which year were banks nationalised in India for the first time?', options: ['1956', '1969', '1980', '1991'], answer: 1, explanation: 'In 1969, 14 major banks were nationalised in India for the first time, during the Fourth Five Year Plan.' },
  { id: 'eco-168', category: 'Economics - Economic Liberalisation Impact', question: 'Economic liberalisation mainly affects which sector(s) of the economy?', options: ['Only the primary sector', 'Only the secondary sector', 'Only the tertiary sector', 'All sectors — primary, secondary and tertiary'], answer: 3, explanation: 'Economic liberalisation, being a broad inflow of foreign investment and technology, affects all sectors of the economy — primary, secondary and tertiary.' },
  { id: 'eco-169', category: 'Economics - Post-1991 Agriculture', question: 'What was a major reason for the decline of the agricultural sector after the 1991 economic reforms?', options: ['A rise in MSP for all crops', 'Increased public investment in irrigation', 'A shift towards export-oriented cash crops with reduced public investment in agriculture', 'Excessive government control over farming'], answer: 2, explanation: 'After 1991, farmers shifted towards export-oriented cash crops (like cotton, rubber) due to global market access, while public investment in agriculture and irrigation declined, contributing to a decline in the agriculture sector.' },
  { id: 'eco-170', category: 'Economics - Cash Crops', question: 'Crops grown mainly for commercial/export purposes rather than for direct consumption, such as cotton, rubber and saffron, are called:', options: ['Basic crops', 'Cash crops', 'Staple crops', 'Subsistence crops'], answer: 1, explanation: 'Cash crops are grown for commercial and export purposes (e.g., cotton, rubber, saffron), as opposed to basic/staple crops (wheat, rice) grown for food consumption.' },
  { id: 'eco-171', category: 'Economics - Eighth Five Year Plan', question: 'During which Five Year Plan did India shift its focus towards Liberalisation and Globalisation, marking a major policy change?', options: ['Sixth Five Year Plan', 'Seventh Five Year Plan', 'Eighth Five Year Plan', 'Ninth Five Year Plan'], answer: 2, explanation: 'The Eighth Five Year Plan (1992-97) marked the shift to Liberalisation, Privatisation and Globalisation (LPG reforms), with a focus on human development and economic liberalisation.' },
  { id: 'eco-172', category: 'Economics - Eleventh Five Year Plan', question: 'In which Five Year Plan was the concept of "Inclusive Growth" first explicitly articulated?', options: ['Ninth Five Year Plan', 'Tenth Five Year Plan', 'Eleventh Five Year Plan', 'Twelfth Five Year Plan'], answer: 2, explanation: 'The concept of Inclusive Growth was first explicitly articulated during the Eleventh Five Year Plan (2007-2012), which focused on education, health, women empowerment and rural development.' },
  { id: 'eco-173', category: 'Economics - Twelfth Five Year Plan', question: 'In which Five Year Plan were the Sustainable Development Goals (SDGs) launched?', options: ['Tenth Five Year Plan', 'Eleventh Five Year Plan', 'Twelfth Five Year Plan', 'None; SDGs are outside the Five Year Plan framework'], answer: 2, explanation: 'The 17 Sustainable Development Goals (SDGs), launched by the United Nations in 2015, coincided with India\'s Twelfth Five Year Plan (2012-17).' },
  { id: 'eco-174', category: 'Economics - Planning Commission vs NITI Aayog', question: 'The Planning Commission was replaced by which body in 2015?', options: ['Finance Commission', 'NITI Aayog', 'RBI', 'SEBI'], answer: 1, explanation: 'The Planning Commission (established 1950) was replaced by NITI Aayog in 2015, which is more flexible with temporary members based on need, unlike the Planning Commission which had permanent members.' },
  { id: 'eco-175', category: 'Economics - Washington Consensus', question: 'The "Washington Consensus" refers to a set of how many economic policy prescriptions given for developing countries in the 1980s-90s?', options: ['5', '10', '15', '20'], answer: 1, explanation: 'The Washington Consensus consists of 10 economic policy prescriptions (by the World Bank, IMF and US Treasury) for developing countries facing economic crises, in the 1980s-90s.' },
  { id: 'eco-176', category: 'Economics - Washington Consensus', question: 'Which of the following is NOT part of the Washington Consensus?', options: ['Trade liberalisation', 'Fiscal discipline', 'Increasing export subsidies', 'Tax reform'], answer: 2, explanation: 'Increasing export subsidies is not part of the Washington Consensus; the consensus actually promotes reducing government intervention. Trade liberalisation, fiscal discipline and tax reform are all part of it.' },
  { id: 'eco-177', category: 'Economics - Competition Act', question: 'The MRTP Act was eventually replaced in 2002 by which Act?', options: ['SEBI Act', 'Competition Act, 2002', 'Companies Act', 'FEMA'], answer: 1, explanation: 'The Competition Act, 2002 replaced the MRTP Act, simplifying regulations for investors and encouraging competition in the Indian market.' },

  // ===================== INDUSTRIAL SECTORS =====================
  { id: 'eco-178', category: 'Economics - Heavy Industries', question: 'Consider the statements about Iron and Steel Industry: (A) Iron and Steel is considered a heavy industry. (R) It requires light raw materials like cotton and rubber. Choose the correct option.', options: ['A is true but R is false', 'A is false but R is true', 'Both A and R are true', 'Both A and R are false'], answer: 0, explanation: 'Iron and Steel is indeed a heavy industry (A is true), but it requires heavy raw materials like iron ore, coal and limestone — not light materials like cotton and rubber (R is false).' },
  { id: 'eco-179', category: 'Economics - Steel Industry', question: 'Why is the Iron and Steel industry called the "Basic Industry"?', options: ['Because it uses the least capital', 'Because raw materials for it are supplied to many other industries', 'Because it requires no machinery', 'Because it employs the fewest workers'], answer: 1, explanation: 'The steel industry is called a "Basic Industry" because it supplies raw material to many other industries, forming the backbone of industrialisation.' },
  { id: 'eco-180', category: 'Economics - Sugar Industry', question: 'Consider the statements about the Sugar Industry in India: (1) The sucrose content of sugarcane decreases during transportation. (2) The sugar industry is seasonal in nature. (3) The industry is unsuitable for cooperative management. (4) Major producers of sugar are Maharashtra and Tamil Nadu. Which statement is INCORRECT?', options: ['Statement 1', 'Statement 2', 'Statement 3', 'Statement 4'], answer: 2, explanation: 'Statement 3 is incorrect — the sugar industry IS suitable for cooperative management, and Maharashtra & Tamil Nadu (statement 4 true) are major producers largely due to cooperative sugar mills.' },
  { id: 'eco-181', category: 'Economics - World Agriculture', question: 'Which country is the world\'s largest producer of sugar, chocolate and coffee?', options: ['India', 'Brazil', 'USA', 'China'], answer: 1, explanation: 'Brazil is the world\'s number one producer of sugar, chocolate and coffee.' },
  // ===================== TYPES OF ECONOMY - APPLIED =====================
  { id: 'ecoh-001', category: 'Economics - Types of Economy', question: 'The relatively easy availability of firearms to ordinary citizens in the USA is often cited as an example linked to which type of economy?', options: ['Socialist economy, due to state control', 'Capitalist economy, due to dominance of private ownership', 'Mixed economy, due to competition', 'Command economy'], answer: 1, explanation: 'In a capitalist economy, items fall largely under private ownership and are sold by private manufacturers to citizens with limited state interference, which is why countries like the USA allow relatively easier private ownership of firearms compared to India or Russia.' },
  { id: 'ecoh-002', category: 'Economics - Types of Economy', question: 'Why do countries like North Korea and Russia rarely appear as market leaders in globally competitive consumer sectors like mobile phones, despite Russia being the world\'s largest arms supplier?', options: ['They lack natural resources', 'They follow a socialist economy with low competition, since the profit motive is absent', 'They have no manufacturing base at all', 'They have banned electronic imports'], answer: 1, explanation: 'Socialist economies are government-controlled with a welfare motive rather than a profit motive, so competition is very low — this is why countries like Russia and North Korea rarely compete globally in consumer markets despite being strong in areas like weapons manufacturing.' },
  { id: 'ecoh-003', category: 'Economics - Types of Economy', question: 'The presence of both SBI/PNB (public sector banks) and HDFC/ICICI (private sector banks) offering a wide variety of options to Indian consumers is a defining feature of which economic system?', options: ['Capitalist economy', 'Socialist economy', 'Mixed economy', 'Command economy'], answer: 2, explanation: 'A Mixed Economy is defined by both public and private sector players operating in parallel, giving consumers a wide range of choices (as seen with banks, petrol companies, and telecom operators in India).' },

  // ===================== LAW OF DEMAND — HARDER =====================
  { id: 'ecoh-004', category: 'Economics - Demand Theory', question: 'A consumer with a normal income reduces their pizza consumption when its price rises, while a very high-income consumer barely notices the same price rise. This difference is best explained by which effect underlying the Law of Demand?', options: ['Substitution effect', 'Income effect', 'Snob effect', 'Bandwagon effect'], answer: 1, explanation: 'This is the Income Effect — since the price increase affects the purchasing power of a normal-income consumer more significantly than a high-income consumer, changing their demand behaviour differently.' },
  { id: 'ecoh-005', category: 'Economics - Demand Theory', question: 'When Thums Up is unavailable and a consumer readily accepts Pepsi instead without traveling elsewhere, this behaviour illustrates which economic concept underlying the Law of Demand?', options: ['Income effect', 'Substitution effect', 'Giffen effect', 'Veblen effect'], answer: 1, explanation: 'This illustrates the Substitution Effect — the consumer switches to a substitute good (Pepsi) that serves the same purpose as Thums Up, because both goods are close substitutes.' },
  { id: 'ecoh-006', category: 'Economics - Demand Theory', question: 'Which of these goods would NOT typically show the standard downward-sloping demand curve behaviour?', options: ['Rice', 'Wheat', 'A luxury sports car (Veblen good)', 'Ordinary vegetables'], answer: 2, explanation: 'A Veblen good (luxury sports car) does not follow the standard Law of Demand — its demand does not fall even as its price rises, since it is bought as a status symbol.' },
  { id: 'ecoh-007', category: 'Economics - Demand Theory', question: 'A theatre owner who suddenly prices a movie ticket at ₹600-1000 instead of the usual ₹200-300 range finds the theatre completely empty. This illustrates which type of demand elasticity?', options: ['Perfectly inelastic demand', 'Unitary elastic demand', 'Perfectly elastic demand', 'Inelastic demand'], answer: 2, explanation: 'This illustrates Perfectly Elastic Demand — even a small increase in price beyond the acceptable range causes demand to fall to zero, since the buyer has many easy alternatives (e.g., OTT platforms).' },

  // ===================== MARKET STRUCTURE — COMPARATIVE =====================
  { id: 'ecoh-008', category: 'Economics - Market Structures', question: 'In which type of market structure is the firm a "price taker" rather than a "price maker"?', options: ['Monopoly', 'Perfect Competition', 'Oligopoly', 'Monopsony'], answer: 1, explanation: 'In Perfect Competition, due to many buyers and sellers of a homogeneous product, individual firms have no power to set prices and must accept the market price — they are "price takers".' },
  { id: 'ecoh-009', category: 'Economics - Market Structures', question: 'Which market structure allows firms to earn super-normal profits in BOTH the short run and the long run?', options: ['Perfect Competition', 'Monopolistic Competition', 'Monopoly', 'None of these'], answer: 2, explanation: 'A Monopoly firm can earn super-normal profits in both the short run and long run due to high entry barriers preventing competition, unlike monopolistic competition where long-run profits settle to normal.' },
  { id: 'ecoh-010', category: 'Economics - Market Structures', question: 'Why is entry into the Indian telecom sector (an oligopoly) extremely difficult for a new company even with ₹50 crore in capital?', options: ['Government bans all new entrants', 'It requires enormous capital investment (in the range of thousands of crores) due to high entry barriers', 'Telecom is a state monopoly only', 'There is no consumer demand for telecom'], answer: 1, explanation: 'Oligopoly markets like telecom have very high entry barriers requiring massive capital investment (in the order of ₹1000 crore or more), which is why only a few dominant firms (Jio, Airtel, Vodafone) exist.' },

  // ===================== NATIONAL INCOME — COMPUTATION-BASED =====================
  { id: 'ecoh-011', category: 'Economics - National Income Calculation', question: 'If Market Cost of a product is ₹25 and the indirect tax included is ₹5 (with no subsidy), what is the Factor Cost?', options: ['₹30', '₹25', '₹20', '₹5'], answer: 2, explanation: 'Factor Cost = Market Cost − Indirect Tax = ₹25 − ₹5 = ₹20.' },
  { id: 'ecoh-012', category: 'Economics - National Income Calculation', question: 'In calculating national income, the correct sequence of steps from GDP to National Income is:', options: ['GDP → (− Depreciation) → NDP → (+ NIFA) → NNP at Market Cost → (− Indirect Tax) → NNP at Factor Cost (National Income)', 'GDP → (+ Depreciation) → NDP → (− NIFA) → National Income', 'GDP → (− Indirect Tax) → NDP → (+ Depreciation) → National Income', 'GDP → (+ NIFA) → National Income directly'], answer: 0, explanation: 'The correct sequence: GDP minus Depreciation gives NDP; NDP plus Net Income From Abroad (NIFA) gives NNP at Market Cost; NNP at Market Cost minus Indirect Tax gives NNP at Factor Cost, which equals National Income.' },
  { id: 'ecoh-013', category: 'Economics - National Income Calculation', question: 'NIFA (Net Income From Abroad) is calculated as:', options: ['Imports − Exports', 'Exports − Imports', 'GDP − NDP', 'NNP − GNP'], answer: 1, explanation: 'NIFA (Net Income From Abroad) = Exports − Imports, representing the net earnings India receives from abroad (e.g., remittances) minus payments made abroad.' },
  { id: 'ecoh-014', category: 'Economics - National Income Calculation', question: 'Why is the raw material cost used in manufacturing a Tejas aircraft NOT separately added while calculating GDP, even though it is a real economic cost?', options: ['Raw material has no monetary value', 'It is already embedded in the final product\'s value, and adding it separately would cause double counting', 'Raw materials are imported and hence excluded', 'GDP only counts services, not goods'], answer: 1, explanation: 'To avoid double counting, GDP calculation only considers the final value of the finished product; intermediate/raw material costs are not counted separately since their value is already included in the final product price.' },
  { id: 'ecoh-015', category: 'Economics - National Income Calculation', question: 'If an aircraft is still under production (work-in-progress) at the end of the accounting year, how is it treated while calculating that year\'s GDP?', options: ['It is counted at 50% of its expected value', 'It is fully counted as production', 'It is NOT counted in that year\'s GDP; it will be counted in the year it is completed', 'It is counted as an import'], answer: 2, explanation: 'GDP counts only finished, ready products for the accounting year. A work-in-progress item is not counted until it is fully completed, to ensure accurate, non-duplicated GDP figures.' },
  { id: 'ecoh-016', category: 'Economics - National Income', question: 'The primary reason Gross National Product (GNP) can be higher than Gross Domestic Product (GDP) for a country like India is:', options: ['Higher exports than imports', 'Positive Net Income From Abroad (income earned by Indians abroad exceeds income earned by foreigners in India)', 'Higher government spending', 'Lower indirect taxes'], answer: 1, explanation: 'GNP = GDP + Net Income From Abroad. If Indians working abroad send back more income than foreigners earn within India, NIFA is positive, making GNP greater than GDP.' },

  // ===================== ELASTICITY & CURVES — HARDER =====================
  { id: 'ecoh-017', category: 'Economics - Curves', question: 'The Laffer Curve is primarily used to explain the relationship between which two variables?', options: ['Unemployment and inflation', 'Tax rate and tax revenue', 'Income inequality and growth', 'Demand and supply'], answer: 1, explanation: 'The Laffer Curve shows that as tax rate increases, tax revenue initially rises, but beyond a certain point, further tax increases cause revenue to decline because people are unable to pay.' },
  { id: 'ecoh-018', category: 'Economics - Curves', question: 'According to the Phillips Curve, during a period of high inflation, what typically happens to unemployment, and why?', options: ['Unemployment rises, because prices become unaffordable', 'Unemployment falls, because increased money supply leads people to spend more, creating jobs', 'Unemployment stays the same', 'There is no relationship'], answer: 1, explanation: 'The Phillips Curve shows an inverse relationship: high inflation means more money circulating in the market, leading to more spending on luxuries/services, which creates jobs and lowers unemployment.' },
  { id: 'ecoh-019', category: 'Economics - Curves', question: 'The Kuznets Curve\'s "inverted-U" relationship implies that inequality in an economy will:', options: ['Rise indefinitely with growth', 'Rise initially with growth, then fall after a certain point (else the economy could collapse)', 'Fall continuously as growth rises', 'Remain constant regardless of growth'], answer: 1, explanation: 'The Kuznets Curve shows inequality rising with per capita income growth up to a point, after which it must fall — otherwise excessive inequality (a shrinking middle class) could destabilise/crash the economy.' },
  { id: 'ecoh-020', category: 'Economics - Elasticity', question: 'A well-known jewellery shop initially quotes ₹500 for a piece but is willing to sell it for as low as ₹350, refusing to go any lower. This range of price flexibility that a seller is willing to work within illustrates:', options: ['Income elasticity', 'Price (bargaining) elasticity', 'Cross elasticity', 'Perfectly inelastic pricing'], answer: 1, explanation: 'This illustrates Price Elasticity in the bargaining sense — the range within which a seller can flexibly adjust price without incurring a loss; below the threshold price, the seller will refuse to sell.' },

  // ===================== MONEY, BANKING — HARDER =====================
  { id: 'ecoh-021', category: 'Economics - Monetary Policy Mechanics', question: 'When RBI wants to inject liquidity into the market during a recession, which sequence of actions does it typically take through Open Market Operations?', options: ['RBI sells government securities, absorbing money from banks', 'RBI buys government securities, releasing money to banks, which increases banks\' lending capacity and lowers interest rates', 'RBI increases CRR, freeing up bank funds', 'RBI increases the Bank Rate to encourage borrowing'], answer: 1, explanation: 'During a recession, RBI buys government securities from banks through OMO, injecting money into banks, which increases their reserves, lowers interest rates, and boosts lending/liquidity in the economy.' },
  { id: 'ecoh-022', category: 'Economics - Monetary Policy Mechanics', question: 'When inflation is very high, RBI typically sells government securities through Open Market Operations. What is the immediate effect on commercial banks?', options: ['Banks receive more money, increasing lending', 'Money flows from banks to RBI, reducing banks\' reserves and lending capacity, raising interest rates', 'Banks are forced to shut down', 'There is no effect on banks'], answer: 1, explanation: 'When RBI sells government securities, banks pay RBI to buy them, so money flows from banks to RBI, reducing bank reserves, decreasing lending capacity, and raising interest rates — this slows down/cools an overheated market.' },
  { id: 'ecoh-023', category: 'Economics - Monetary Policy Mechanics', question: 'If a person reduces their car loan EMI purchase decision because the Repo Rate has been lowered by RBI, which underlying chain of events explains this?', options: ['RBI directly lends to the consumer at a lower rate', 'RBI lowers repo rate → banks borrow cheaply from RBI → banks pass on lower interest rates to consumers → loans become cheaper', 'The consumer\'s income increased due to repo rate cut', 'Repo rate has no link to consumer loans'], answer: 1, explanation: 'When RBI lowers the repo rate, banks can borrow from RBI at a cheaper rate, and this benefit is passed on to consumers as lower interest rates on loans like home/auto loans.' },
  { id: 'ecoh-024', category: 'Economics - Money Multiplier', question: 'Why does cash held by the public (rather than deposited/invested) reduce the Money Multiplier in an economy?', options: ['Cash held idle earns no returns and does not circulate through the banking system to generate further lending', 'Cash held by the public is illegal', 'Cash held by the public increases bank reserves', 'It has no impact at all'], answer: 0, explanation: 'Idle cash held by the public does not enter the banking system, so it cannot be used by banks to create further credit/loans, thereby reducing the money multiplier effect of the economy.' },
  { id: 'ecoh-025', category: 'Economics - Banking Terms', question: 'Which of the following statements about Marginal Standing Facility (MSF) is correct?', options: ['It is used for routine daily borrowing at the lowest possible rate', 'It allows banks to borrow from RBI at a higher-than-normal rate only during emergency/crisis situations', 'It is a facility only for foreign banks', 'It replaced the Repo Rate mechanism entirely'], answer: 1, explanation: 'MSF is a special emergency window that allows banks to borrow overnight funds from RBI at a rate higher than the repo rate, used only during liquidity emergencies.' },
  { id: 'ecoh-026', category: 'Economics - Coinage & Currency', question: 'Why does the ₹1 note/coin carry the signature of the Finance Secretary rather than the RBI Governor?', options: ['It is a printing error carried forward historically', 'Because the ₹1 note is issued under the Coinage Act by the Government of India directly, guaranteeing the validity of RBI-issued currency', 'Because the RBI Governor does not have signing authority', 'Because ₹1 notes are printed abroad'], answer: 1, explanation: 'The ₹1 note is issued directly by the Government of India under the Coinage Act (not the RBI Act), and it symbolically guarantees that RBI — an undertaking of the government — is authorised to issue the Rupee currency; hence it is signed by the Finance Secretary, not the RBI Governor.' },
  { id: 'ecoh-027', category: 'Economics - FEMA', question: 'What is the key structural difference between FERA (1973) and FEMA (2000) regarding violations?', options: ['FERA had civil penalties; FEMA introduced criminal penalties', 'FERA treated violations as criminal offences; FEMA introduced milder civil penalties', 'Both had identical penalty structures', 'FERA applied only to imports; FEMA applies only to exports'], answer: 1, explanation: 'Under FERA, violations were criminalised with strict punishments (including jail), whereas under FEMA, violations attract civil penalties (monetary), with provisions like Lok Adalat settlements instead of criminal prosecution.' },

  // ===================== INFLATION — HARDER =====================
  { id: 'ecoh-028', category: 'Economics - Inflation Analysis', question: 'If food and fuel prices rise so sharply that even "core inflation" measures can no longer exclude them meaningfully, this overall extreme measure is referred to as:', options: ['Disinflation', 'Deflation', 'Headline inflation', 'Stagflation'], answer: 2, explanation: 'Headline Inflation is the broadest measure of inflation that includes ALL items, including volatile food and fuel prices, unlike Core Inflation which excludes them.' },
  { id: 'ecoh-029', category: 'Economics - Inflation Analysis', question: 'Which combination of factors defines "Stagflation", making it one of the most difficult economic situations for policymakers to address?', options: ['Low inflation with high growth', 'High inflation combined with stagnant growth and rising unemployment', 'Deflation with high growth', 'Low unemployment with low inflation'], answer: 1, explanation: 'Stagflation is considered the worst macroeconomic situation because it combines high inflation, stagnant growth, and rising unemployment simultaneously — making both fiscal and monetary policy tools less effective.' },
  { id: 'ecoh-030', category: 'Economics - Inflation Analysis', question: 'A person who breaks their Fixed Deposit (FD) early to meet rising daily expenses during high inflation is engaging in what type of economic behaviour, and what is its broader macroeconomic effect?', options: ['Investment, which boosts the economy', 'Disinvestment, which reduces funds available for the economy/banks to lend further', 'Saving, which has no macro effect', 'Speculation, which increases stock prices'], answer: 1, explanation: 'Breaking an FD converts a previously "invested" asset into consumption spending — a form of disinvestment — reducing the pool of funds banks/the government have available for further investment in the economy.' },

  // ===================== FISCAL/MONETARY POLICY — HARDER =====================
  { id: 'ecoh-031', category: 'Economics - Fiscal vs Monetary', question: 'If a government wants to boost employment specifically through direct hiring and infrastructure spending, which policy tool is most directly relevant?', options: ['Monetary policy (via RBI)', 'Fiscal policy (via Government spending)', 'Exchange rate policy', 'Trade policy'], answer: 1, explanation: 'Direct government hiring and infrastructure spending falls under Fiscal Policy, controlled by the Government of India, as opposed to Monetary Policy which deals with money supply and interest rates via the RBI.' },
  { id: 'ecoh-032', category: 'Economics - Fiscal Deficit', question: 'If a country\'s Fiscal Deficit consistently exceeds its GDP growth rate ratio over several years, what is the most likely long-term consequence?', options: ['Automatic reduction in inflation', 'Risk of economic instability, rising debt burden, and inflation risk', 'Guaranteed increase in exports', 'No consequence as long as GDP is positive'], answer: 1, explanation: 'A persistently high fiscal deficit (relative to GDP growth) increases government borrowing/debt burden, and can trigger inflation risk and long-term economic instability, which is why fiscal deficit targets (like 4.4% of GDP) are set under FRBM-type frameworks.' },
  { id: 'ecoh-033', category: 'Economics - FRBM Act', question: 'The FRBM Act mandates the Finance Minister to submit which type of policy documents to Parliament?', options: ['Only the Union Budget speech', 'Medium-term fiscal policy statements and fiscal strategy statements', 'Only RBI\'s monetary policy report', 'Only the Economic Survey'], answer: 1, explanation: 'Under the FRBM Act (2003), the Finance Minister must submit medium-term fiscal policy statements and fiscal strategy statements to Parliament, ensuring transparency and accountability in government finances.' },

  // ===================== BUDGET TYPES — HARDER =====================
  { id: 'ecoh-034', category: 'Economics - Budgeting Systems', question: 'Why was India\'s Performance-Based Budgeting system (used until around 1980) considered inefficient over the long run?', options: ['It required too much documentation', 'It simply repeated prior-year allocations without adjusting to changing needs and currency value over time', 'It was banned by the Constitution', 'It only applied to defence spending'], answer: 1, explanation: 'Performance-based budgeting mechanically carried forward the previous year\'s allocation (plus/minus small adjustments) without a fresh assessment, failing to account for changing needs, inflation, and currency devaluation over time — much like giving a growing child the same fixed pocket money for 15 years.' },
  { id: 'ecoh-035', category: 'Economics - Budgeting Systems', question: 'Under Zero-Based Budgeting, how does the Ministry of Defence justify its annual allocation, in contrast to the old Performance-Based system?', options: ['It automatically receives the same amount as the previous year', 'Each wing (Army, Navy, Air Force) separately submits fresh demand for equipment/resources needed that year, and the total budget is built from these demands', 'The Finance Ministry decides arbitrarily without consultation', 'Defence budget is fixed permanently by the Constitution'], answer: 1, explanation: 'In Zero-Based Budgeting, each department/wing submits a fresh justification (e.g., Army, Navy, Air Force each stating specific equipment needs) rather than simply continuing from the previous year\'s figure treated as a baseline.' },
  { id: 'ecoh-036', category: 'Economics - Budgeting Systems', question: 'The Namami Gange project is a good example of which type of budget, given that its allocation was revised upward multiple times based on periodic review?', options: ['Zero-based budget', 'Gender-based budget', 'Outcome budget', 'Green budget only'], answer: 2, explanation: 'An Outcome Budget involves periodic review (e.g., every 3 months) of a scheme\'s performance, with allocations increased based on outcomes achieved — as happened with the Namami Gange project, whose budget grew significantly over time.' },
  { id: 'ecoh-037', category: 'Economics - Deficit Calculations', question: 'If a government\'s Total Expenditure is ₹100, Revenue Receipts are ₹70, and Non-Debt Capital Receipts are ₹10, what is the Fiscal Deficit?', options: ['₹10', '₹20', '₹30', '₹80'], answer: 1, explanation: 'Fiscal Deficit = Total Expenditure − (Revenue Receipts + Non-Debt Capital Receipts) = 100 − (70+10) = ₹20.' },
  { id: 'ecoh-038', category: 'Economics - Deficit Calculations', question: 'If Fiscal Deficit is ₹50 crore and Interest Payments are ₹15 crore, what is the Primary Deficit?', options: ['₹65 crore', '₹50 crore', '₹35 crore', '₹15 crore'], answer: 2, explanation: 'Primary Deficit = Fiscal Deficit − Interest Payments = 50 − 15 = ₹35 crore.' },

  // ===================== PSU CLASSIFICATION — HARDER =====================
  { id: 'ecoh-039', category: 'Economics - PSU Classification', question: 'What is the precise sequence of criteria a company must meet to be upgraded from Miniratna to Navratna, and finally to Maharatna status?', options: ['Random government selection with no fixed criteria', 'Continuous profitability for 3 years at each stage, combined with holding the immediately preceding status for the previous 3 years', 'Only a company\'s size/employee count matters', 'Only foreign investment level matters'], answer: 1, explanation: 'To move up the PSU hierarchy, a company must show continuous profitability for the last 3 years AND must have held the immediately lower status (e.g., Navratna) continuously for the preceding 3 years before being considered for Maharatna.' },
  { id: 'ecoh-040', category: 'Economics - PSU Classification', question: 'Which criterion is REQUIRED for a company to be classified as Maharatna but is NOT mandatory for Navratna or Miniratna companies?', options: ['Profitability for 3 consecutive years', 'Global presence — operations/business in countries outside India', 'Being 100% government-owned', 'Being listed on the stock exchange'], answer: 1, explanation: 'A Maharatna company must have a global presence (operations in other countries), which is not a mandatory requirement for Navratna or Miniratna companies.' },
  { id: 'ecoh-041', category: 'Economics - PSU Classification', question: 'Within the Miniratna category, what distinguishes a Category-I Miniratna company from a Category-II Miniratna company in terms of investment power?', options: ['Category-I can invest up to ₹500 crore without government approval; Category-II can invest up to ₹300 crore', 'Category-I can invest up to ₹300 crore; Category-II can invest up to ₹500 crore', 'Both categories have identical investment limits', 'Category-II companies have unlimited investment power'], answer: 0, explanation: 'Category-I Miniratna companies can invest up to ₹500 crore without government approval, while Category-II Miniratna companies (smaller in scale) can invest up to ₹300 crore.' },

  // ===================== FIVE YEAR PLANS — HARDER =====================
  { id: 'ecoh-042', category: 'Economics - Five Year Plans', question: 'The First Five Year Plan (1951-56), based on the Harrod-Domar Model, achieved a growth rate of approximately how much against its target of 2.1%?', options: ['1.5%', '2.1% exactly (met the target)', '3.6% (exceeded the target)', '5% (far exceeded)'], answer: 2, explanation: 'The First Five Year Plan targeted a growth rate of 2.1% but actually achieved approximately 3.6% growth — nearly double the target, making it a highly successful plan.' },
  { id: 'ecoh-043', category: 'Economics - Five Year Plans', question: 'Which government body, whose Chairperson was always the Prime Minister, was responsible for allocating funds to states before being replaced in 2015?', options: ['Finance Commission', 'Planning Commission', 'NITI Aayog', 'Union Cabinet'], answer: 1, explanation: 'The Planning Commission (est. 1950), whose Chairperson was always the Prime Minister, was a non-statutory, non-constitutional body responsible for allocating resources to states and ministries; it was replaced by NITI Aayog in 2015.' },
  { id: 'ecoh-044', category: 'Economics - Five Year Plans', question: 'What is a key structural difference between the Planning Commission and NITI Aayog regarding membership?', options: ['Planning Commission had permanent members (8-12); NITI Aayog has flexible, temporary members that can be added or removed based on need', 'NITI Aayog has permanent members while Planning Commission had temporary ones', 'Both have identical fixed membership structures', 'Membership rules are identical for both bodies'], answer: 0, explanation: 'The Planning Commission had a fixed set of permanent members (typically 8-12), whereas NITI Aayog is far more flexible, allowing temporary members to be added for specific projects and removed once the task is complete.' },
  { id: 'ecoh-045', category: 'Economics - Five Year Plans', question: 'During the "Plan Holiday" (1966-69), what was the approximate extent of the Rupee\'s devaluation as part of India\'s economic crisis response?', options: ['About 10%', 'About 20%', 'About 36.5%', 'About 50%'], answer: 2, explanation: 'During this crisis period, the Rupee devalued by approximately 36.5%, meaning nearly one-third of its value was lost, reflecting the severity of the economic crisis caused by the wars and drought.' },
  { id: 'ecoh-046', category: 'Economics - Five Year Plans', question: 'Under which US aid programme did India import large quantities of wheat during the food crisis of 1965-66?', options: ['Marshall Plan', 'PL-480', 'Lend-Lease Act', 'Green Revolution Aid Programme'], answer: 1, explanation: 'Under the American PL-480 programme, India imported large quantities of wheat during the severe food crisis of 1965-66, despite being an agrarian nation.' },
  { id: 'ecoh-047', category: 'Economics - Five Year Plans', question: 'Which country primarily supported India during the Cold War era (1947-1990), leading to minimal support from the USA during most of this period?', options: ['United Kingdom', 'Soviet Union (Russia)', 'France', 'Germany'], answer: 1, explanation: 'During the Cold War, the Soviet Union (now Russia) was India\'s primary ally, while the USA largely supported Pakistan and provided minimal support to India except during isolated crises like the 1965-66 food shortage.' },
  { id: 'ecoh-048', category: 'Economics - Five Year Plans', question: 'The Fourth Five Year Plan (1969-74) came shortly after which major nationalisation event in Indian banking history?', options: ['Nationalisation of insurance companies', 'Nationalisation of 14 major banks (1969)', 'Nationalisation of the steel industry', 'Nationalisation of the coal industry'], answer: 1, explanation: 'The nationalisation of 14 major banks took place in 1969, right at the start of the Fourth Five Year Plan, aiming to expand banking access and support economic goals of the plan.' },
  { id: 'ecoh-049', category: 'Economics - Five Year Plans', question: 'What major event severely disrupted the Fourth Five Year Plan (1969-74), leading to inflation and a foreign exchange shortage, despite improvements in food production?', options: ['The 1962 Indo-China War', 'The 1971 Indo-Pak War and formation of Bangladesh', 'The 1991 BOP crisis', 'The 1979 oil crisis alone'], answer: 1, explanation: 'The 1971 Indo-Pak War, which led to the creation of Bangladesh, caused inflation and foreign exchange shortages during the Fourth Five Year Plan, even though food production had improved by then.' },
  { id: 'ecoh-050', category: 'Economics - Five Year Plans', question: 'The "20 Point Programme" launched in 1975 coincided with which major political event in Indian history?', options: ['India\'s independence', 'The Emergency (1975-77)', 'The 1991 economic reforms', 'The formation of NITI Aayog'], answer: 1, explanation: 'The 20 Point Programme, launched by Indira Gandhi in 1975 as part of the "Garibi Hatao" initiative, coincided with the declaration of the Emergency (1975-77).' },
  { id: 'ecoh-051', category: 'Economics - Five Year Plans', question: 'Why was the "Rolling Plan" (introduced in 1978 under Morarji Desai) considered more flexible than the traditional Five Year Plan system?', options: ['It set fixed five-year targets that could never be revised', 'It set annual targets that could be reviewed and revised any time based on changing circumstances', 'It abolished all planning altogether', 'It only applied to defence spending'], answer: 1, explanation: 'The Rolling Plan replaced fixed five-year targets with annual targets that could be reviewed and adjusted flexibly, unlike the traditional system where targets remained unchanged for the full 5-year period.' },
  { id: 'ecoh-052', category: 'Economics - Five Year Plans', question: 'IDBI Bank, which played a key financing role during the Fifth Five Year Plan, was originally established in 1964 as a subsidiary of which institution?', options: ['RBI', 'LIC (Life Insurance Corporation)', 'SBI', 'World Bank'], answer: 1, explanation: 'IDBI (Industrial Development Bank of India) was established in 1964 as a subsidiary of LIC and later converted into a full-fledged bank around 2004.' },
  { id: 'ecoh-053', category: 'Economics - Five Year Plans', question: 'Which was the correct focus sequence of India\'s first three Five Year Plans in terms of priority sector?', options: ['Agriculture → Heavy Industries → (Plan disrupted by wars, drought)', 'Heavy Industries → Agriculture → IT sector', 'Services → Manufacturing → Agriculture', 'IT → Agriculture → Heavy Industries'], answer: 0, explanation: 'The First Plan (1951-56) focused on Agriculture, the Second Plan (1956-61) focused on Heavy Industries, and the Third Plan (1961-66) was disrupted by wars (1962, 1965) and drought, ultimately failing to meet its targets.' },
  { id: 'ecoh-054', category: 'Economics - Five Year Plans', question: 'Which of the following correctly matches the Five Year Plan with its associated Prime Minister/era and key theme?', options: ['Seventh Plan (1985-90) — Rajiv Gandhi era — small & cottage industries, employment generation', 'Second Plan (1956-61) — Rajiv Gandhi era — IT sector', 'Eleventh Plan (2007-12) — Nehru era — heavy industries', 'Fourth Plan (1969-74) — Rajiv Gandhi era — inclusive growth'], answer: 0, explanation: 'The Seventh Five Year Plan (1985-90) is associated with the Rajiv Gandhi era, focusing on small & cottage industries, employment generation, and technology.' },
  { id: 'ecoh-055', category: 'Economics - Five Year Plans', question: 'The Eighth Five Year Plan (1992-97), coinciding with the LPG reforms, saw which Indian company emerge as a global leader in the IT/software services sector?', options: ['Infosys', 'Tata Consultancy Services (TCS)', 'Wipro', 'HCL'], answer: 1, explanation: 'During and after the Eighth Five Year Plan, following privatisation and liberalisation, Tata Consultancy Services (TCS) emerged as the largest software services company not just in India, but in Asia.' },
  { id: 'ecoh-056', category: 'Economics - Five Year Plans', question: 'Which of the following statements is/are correct? (1) The Sixth Five Year Plan focused on income growth and technological modernisation. (2) The Third Five Year Plan failed due to war, rupee devaluation and food crisis. Choose the correct option.', options: ['Only statement 1', 'Only statement 2', 'Both statements are correct', 'Neither statement is correct'], answer: 2, explanation: 'The Sixth Five Year Plan did emphasise income growth and technological modernisation (statement 1 true), and the Third Five Year Plan indeed failed due to the war, rupee devaluation and food crisis (statement 2 true) — both statements are correct.' },

  // ===================== POVERTY & COMMITTEES — HARDER =====================
  { id: 'ecoh-057', category: 'Economics - Poverty Line Committees', question: 'Which committee first established India\'s official poverty line based on a calorie-intake approach, recommending 2400 kcal/day for rural areas and 2100 kcal/day for urban areas?', options: ['Lakdawala Committee', 'Alagh Committee (1979)', 'Tendulkar Committee', 'Rangarajan Committee'], answer: 1, explanation: 'The Alagh Committee (1979) was India\'s first official poverty line committee, using a calorie-based approach with 2400 kcal/day for rural and 2100 kcal/day for urban populations.' },
  { id: 'ecoh-058', category: 'Economics - Poverty Line Committees', question: 'Which committee was the FIRST to move away from a purely calorie-based poverty measure and instead adopt an expenditure-based approach covering health, education and clothing?', options: ['Alagh Committee (1979)', 'Lakdawala Committee (1993)', 'Tendulkar Committee (2009)', 'Rangarajan Committee (2014)'], answer: 2, explanation: 'The Tendulkar Committee (2009) was the first to abandon the calorie-based method entirely, adopting an expenditure-based poverty measure incorporating health, education, clothing and fuel costs.' },
  { id: 'ecoh-059', category: 'Economics - Poverty Line Committees', question: 'The Rangarajan Committee (2014), which suggested a higher poverty line than the Tendulkar Committee, recommended monthly per capita expenditure thresholds of approximately how much for rural and urban areas respectively?', options: ['₹816 rural, ₹1000 urban', '₹972 rural, ₹1407 urban', '₹1000 rural, ₹1500 urban', '₹500 rural, ₹800 urban'], answer: 1, explanation: 'The Rangarajan Committee (2014) recommended a higher poverty threshold of ₹972 per month for rural areas and ₹1407 per month for urban areas, though this was never officially adopted.' },
  { id: 'ecoh-060', category: 'Economics - Poverty Measurement', question: 'India\'s current official poverty measurement framework is based on which methodology, introduced in 2015?', options: ['Lakdawala Committee\'s calorie method', 'NITI Aayog\'s Multidimensional Poverty Index (health, education, living standards)', 'Rangarajan Committee\'s expenditure method', 'World Bank\'s $1.90/day method exclusively'], answer: 1, explanation: 'Since 2015, India uses the NITI Aayog\'s Multidimensional Poverty Index, which considers health, education and living standards (rather than just income/expenditure) to determine poverty.' },

  // ===================== EMPLOYMENT & UNEMPLOYMENT — HARDER =====================
  { id: 'ecoh-061', category: 'Economics - Unemployment Analysis', question: 'Consider the statements: (1) A person who resigns from one government job on the day of selection for another job, but has a 6-month gap before the new joining date, is technically unemployed during this gap due to Frictional Unemployment. (2) This is the same as Cyclical Unemployment. Which is correct?', options: ['Only statement 1 is correct', 'Only statement 2 is correct', 'Both are correct', 'Neither is correct'], answer: 0, explanation: 'This scenario is a textbook example of Frictional Unemployment (short-term unemployment while transitioning between jobs), not Cyclical Unemployment (which is tied to economic recession/business cycles).' },
  { id: 'ecoh-062', category: 'Economics - Unemployment Analysis', question: 'Why is Educated Unemployment typically found more in urban areas than rural areas of India?', options: ['Rural areas have lower literacy and education levels overall, so fewer people face this specific type of unemployment', 'Urban areas have no jobs at all', 'Rural areas have a surplus of highly skilled jobs', 'Educated unemployment does not exist in India'], answer: 0, explanation: 'Since education levels are relatively lower in rural areas, the phenomenon of educated individuals struggling to find suitable jobs (educated unemployment) is more prevalent in urban areas where education levels are higher but job availability doesn\'t match.' },
  { id: 'ecoh-063', category: 'Economics - Unemployment Analysis', question: 'A factory that previously employed 10 workers for a task now uses one machine to do the same job, making all 10 workers redundant. This is a direct example of:', options: ['Structural unemployment', 'Technological unemployment', 'Cyclical unemployment', 'Frictional unemployment'], answer: 1, explanation: 'This is Technological Unemployment — jobs lost specifically because machines/automation replace human labour for the same task.' },

  // ===================== RURAL-URBAN, GDP, DEVELOPMENT — HARDER =====================
  { id: 'ecoh-064', category: 'Economics - Structural Transformation', question: 'The fact that agriculture\'s contribution to India\'s GDP has declined while the percentage of workforce dependent on agriculture remains very high (around 65%) is best described as evidence of:', options: ['Successful structural transformation', 'Failed structural transformation, indicating low productivity and disguised unemployment in agriculture', 'A booming rural economy', 'A shortage of agricultural workers'], answer: 1, explanation: 'This mismatch — high workforce dependence but declining GDP share — indicates failed structural transformation, reflecting low agricultural productivity and hidden/disguised unemployment among farm workers who have not moved to more productive sectors.' },
  { id: 'ecoh-065', category: 'Economics - GDP Limitations', question: 'Which of the following is a valid criticism of using GDP alone as a measure of a nation\'s overall wellbeing?', options: ['GDP always overstates a country\'s military strength', 'GDP does not account for environmental degradation, resource depletion, or how income is distributed among the population', 'GDP is always negative for developing countries', 'GDP cannot be measured for any country'], answer: 1, explanation: 'A key limitation of GDP is that it does not capture environmental degradation, depreciation of capital assets, or the distribution of income/wealth across the population — meaning GDP growth does not necessarily reflect actual improvement in citizens\' quality of life.' },
  { id: 'ecoh-066', category: 'Economics - Per Capita Income', question: 'A state government offering tax holidays, subsidised electricity and simplified paperwork to attract industries (as Gujarat did to attract Tata, Reliance and other conglomerates) primarily helps increase which economic indicator?', options: ['Domestic Savings Rate only', 'Foreign Direct Investment (FDI) and industrial growth', 'Fiscal Deficit exclusively', 'Sex Ratio'], answer: 1, explanation: 'Offering incentives like tax holidays and subsidies to businesses is a strategy to attract industrial investment and Foreign Direct Investment (FDI), as seen in Gujarat\'s success in attracting major industrial houses.' },

  // ===================== TRADE, WTO, FOREIGN EXCHANGE — HARDER =====================
  { id: 'ecoh-067', category: 'Economics - Foreign Trade', question: 'Which of the following best distinguishes "Bilateral Trade" from "Volume of Trade" as used in economic terminology?', options: ['Bilateral trade always involves profit-driven exchange between two nations, while volume of trade refers to commodity exchange purely to strengthen diplomatic relations', 'They are exactly the same concept', 'Volume of trade only applies to multilateral agreements', 'Bilateral trade only applies to defence goods'], answer: 0, explanation: 'Bilateral Trade involves commercial, profit-oriented exchange of goods between two countries, whereas Volume of Trade (as discussed) can refer to exchanges (like flowers for apples) done mainly to build/strengthen diplomatic and trade relations rather than for direct necessity or profit.' },
  { id: 'ecoh-068', category: 'Economics - FDI Determinants', question: 'If Country A raises its corporate tax rate on foreign manufacturers from 10% to 20%, what is the most likely impact on FDI inflows into Country A?', options: ['FDI will increase because higher taxes attract serious investors', 'FDI will likely decrease because reduced profit margins make Country A less attractive compared to lower-tax alternatives', 'FDI will remain completely unaffected', 'FDI is unrelated to tax rates'], answer: 1, explanation: 'Higher corporate/business taxes reduce the profit margin for foreign companies, making a country less attractive for investment compared to nations offering lower tax rates — directly reducing FDI inflows.' },

  // ===================== ADVANCED MISC. CONCEPTS =====================
  { id: 'ecoh-069', category: 'Economics - Consumer Behaviour', question: 'The "Labubu" toy trend, where people bought the toy mainly because celebrities and others were buying it, is a real-world example of which economic effect?', options: ['Snob effect', 'Bandwagon effect', 'Giffen effect', 'Veblen effect (exclusively)'], answer: 1, explanation: 'This is a classic example of the Bandwagon Effect, where demand for a product increases because people see others (especially celebrities) buying it and want to follow the trend.' },
  { id: 'ecoh-070', category: 'Economics - Opportunity Cost', question: 'A buyer who was offered a Scorpio-N at a discounted Diwali price of ₹26.5 lakh but instead purchased a Skoda Kodiaq has an "opportunity cost" equal to:', options: ['The price of the Skoda Kodiaq', 'The value of the Scorpio-N deal forgone (₹26.5 lakh offer)', 'Zero, since no money was spent on the Scorpio-N', 'The difference between the two car prices'], answer: 1, explanation: 'Opportunity Cost is the value of the next best alternative forgone — in this case, the discounted Scorpio-N deal that was given up when the buyer chose the Skoda Kodiaq instead.' },
  { id: 'ecoh-071', category: 'Economics - Credit Terms', question: 'A borrower with a CIBIL score above 780 typically receives which of the following benefits from a bank?', options: ['Reduced loan amount regardless of request', 'Easier and potentially larger loan approval, reflecting lower perceived risk to the bank', 'Automatic loan rejection due to over-qualification', 'No effect on loan approval at all'], answer: 1, explanation: 'A high CIBIL score (above 780, generally excellent above 800) reflects strong financial discipline and repayment history, making banks more willing to approve larger loan amounts with lower perceived risk.' },
  { id: 'ecoh-072', category: 'Economics - Credit Terms', question: 'Why do banks typically prefer secured loans over unsecured loans, and what is the trade-off for borrowers taking unsecured loans (like personal loans)?', options: ['Secured loans have no interest; unsecured loans always have very low interest', 'Secured loans reduce the bank\'s risk via collateral, while unsecured loans (with no collateral) carry higher interest rates due to higher risk', 'There is no difference between the two types', 'Secured loans are illegal in India'], answer: 1, explanation: 'Secured loans (like home/auto loans) are backed by collateral, reducing the bank\'s risk and thus offering lower interest rates, whereas unsecured loans (like personal loans) carry no collateral, so banks charge much higher interest rates (sometimes 16-20%) to offset the higher risk.' },
  { id: 'ecoh-073', category: 'Economics - Distress Sale', question: 'A person who bought gold worth ₹10 lakh, and is forced to sell it for exactly ₹10 lakh (with zero profit) during an emergency when markets are shut, is engaging in:', options: ['Speculative investment', 'A profitable sale', 'A distress sale', 'Arbitrage'], answer: 2, explanation: 'This is a Distress Sale — an asset (gold in this case) is sold in an emergency without earning the expected profit (or even at a loss), purely due to urgent need for liquidity.' },
  { id: 'ecoh-074', category: 'Economics - Monopoly Example', question: 'If a state government awards all major infrastructure contracts to a single private company, creating a situation where only that company can bid for future projects, this scenario best represents:', options: ['Perfect competition', 'Monopoly (control by a single player)', 'Monopsony', 'Oligopoly'], answer: 1, explanation: 'When only a single company controls the supply/provision of a good or service (like infrastructure contracts) with no alternatives available, this represents a Monopoly situation.' },

  // ===================== STATEMENT-BASED / ASSERTION-REASON (HARD) =====================
  { id: 'ecoh-075', category: 'Economics - Assertion-Reason', question: 'Assertion (A): India\'s GDP growth rate has not been continuously increasing over the last decade. Reason (R): GDP at market prices has grown steadily due to persistently rising prices of goods and services. Choose the correct option.', options: ['Both A and R are true, and R correctly explains A', 'Both A and R are true, but R does not explain A', 'A is true, R is false', 'A is false, R is true'], answer: 1, explanation: 'Both statements are factually true — GDP growth rate has fluctuated (not continuously risen), and GDP at market prices has risen steadily due to rising prices — but R does not directly explain why the growth RATE fluctuated; they describe two separate observations.' },
  { id: 'ecoh-076', category: 'Economics - Assertion-Reason', question: 'Assertion (A): The Third Five Year Plan (1961-66) is considered a failure. Reason (R): It coincided with the Indo-China War (1962), Indo-Pak War (1965), a severe drought, and rupee devaluation. Choose the correct option.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is not the correct explanation of A', 'A is true, R is false', 'A is false, R is true'], answer: 0, explanation: 'The Third Plan is indeed considered a failure (A true), and this failure is directly and correctly explained by the combination of two wars, drought, and rupee devaluation occurring during this period (R correctly explains A).' },
  { id: 'ecoh-077', category: 'Economics - Assertion-Reason', question: 'Assertion (A): Import Substitution policy was followed during India\'s early Five Year Plans. Reason (R): It aimed to protect newly established (infant) domestic industries from powerful foreign competition. Choose the correct option.', options: ['Both A and R are true, and R correctly explains A', 'Both A and R are true, but R does not explain A', 'A is true, R is false', 'A is false, R is true'], answer: 0, explanation: 'Import Substitution was indeed the policy followed (A true), and it was precisely aimed at protecting newly established domestic industries from stronger foreign competitors (R correctly explains A), rather than letting foreign companies dominate the Indian market directly.' },
  { id: 'ecoh-078', category: 'Economics - Assertion-Reason', question: 'Assertion (A): The 1991 economic reforms (LPG) are described as "Stabilisation" measures with a short-term objective. Reason (R): The IMF provided assistance conditional upon India implementing these measures to correct the Balance of Payments crisis. Choose the correct option.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R does not explain A', 'A is true, R is false', 'A is false, R is true'], answer: 0, explanation: 'The Stabilisation measures were indeed short-term (A true), and this is because they were a condition set by the IMF for providing financial assistance to correct India\'s Balance of Payments crisis (R correctly explains A).' },
  { id: 'ecoh-079', category: 'Economics - Assertion-Reason', question: 'Assertion (A): Disinvestment reduces the monopoly power of Public Sector Undertakings. Reason (R): Disinvestment transfers government stakes to private players, increasing private sector participation. Choose the correct option.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R does not explain A', 'A is true, R is false', 'A is false, R is true'], answer: 0, explanation: 'Disinvestment does reduce PSU monopoly power (A true), precisely because it transfers ownership stakes to private companies, increasing private sector competition and participation (R correctly explains A).' },
  { id: 'ecoh-080', category: 'Economics - Assertion-Reason', question: 'Assertion (A): India followed the strategy of Import Substitution before 1991 but continues importing selectively even today (e.g., from China). Reason (R): Even after liberalisation, selective imports are sometimes necessary to protect domestic industries in a globalised world with international e-commerce access. Choose the correct option.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R does not explain A', 'A is true, R is false', 'A is false, R is true'], answer: 0, explanation: 'India does continue to selectively import (A true), and this is because in a globalised world with easy international e-commerce access, some level of import is still needed to protect domestic industry from being replaced entirely by unrestricted foreign competition (R correctly explains A).' },

  // ===================== ADVANCED SYNTHESIS QUESTIONS =====================
  { id: 'ecoh-081', category: 'Economics - Synthesis', question: 'Which sequence correctly represents the chronological order of India\'s major poverty-line/measurement committees?', options: ['Tendulkar (2009) → Alagh (1979) → Rangarajan (2014) → Lakdawala (1993)', 'Alagh (1979) → Lakdawala (1993) → Tendulkar (2009) → Rangarajan (2014)', 'Lakdawala (1993) → Alagh (1979) → Rangarajan (2014) → Tendulkar (2009)', 'Rangarajan (2014) → Tendulkar (2009) → Lakdawala (1993) → Alagh (1979)'], answer: 1, explanation: 'The correct chronological order is: Alagh Committee (1979) → Lakdawala Committee (1993) → Tendulkar Committee (2009) → Rangarajan Committee (2014).' },
  { id: 'ecoh-082', category: 'Economics - Synthesis', question: 'Which sequence correctly represents the chronological order of these Indian economic/monetary reforms?', options: ['FEMA (2000) → Bank Nationalisation (1969) → Competition Act (2002) → MRTP Act (1969)', 'Bank Nationalisation (1969) → MRTP Act (1969) → FEMA (2000) → Competition Act (2002)', 'Competition Act (2002) → FEMA (2000) → MRTP Act (1969) → Bank Nationalisation (1969)', 'MRTP Act (1969) → Competition Act (2002) → Bank Nationalisation (1969) → FEMA (2000)'], answer: 1, explanation: 'Correct order: Bank Nationalisation (1969, alongside MRTP Act 1969) → FEMA applied (2000) → Competition Act (2002), which replaced the MRTP Act.' },
  { id: 'ecoh-083', category: 'Economics - Synthesis', question: 'Which of the following pairs is INCORRECTLY matched?', options: ['V.K.R.V. Rao — First scientific estimate of India\'s National Income', 'Dadabhai Naoroji — Drain of Wealth Theory', 'P.C. Mahalanobis — Human Development Index', 'Mahbub ul Haq — Human Development Index'], answer: 2, explanation: 'P.C. Mahalanobis is associated with the Five Year Plans model (Mahalanobis Model), NOT the Human Development Index. The Human Development Index was developed by Mahbub ul Haq.' },
  { id: 'ecoh-084', category: 'Economics - Synthesis', question: 'Which of the following pairs is INCORRECTLY matched?', options: ['Repo Rate — RBI lends to banks (short term)', 'Reverse Repo Rate — RBI borrows from banks', 'Bank Rate — RBI lends to banks (long term)', 'MSF — Government lends to RBI'], answer: 3, explanation: 'MSF (Marginal Standing Facility) is a facility where banks borrow from RBI at a higher rate during emergencies — it does NOT involve the government lending to RBI.' },
  { id: 'ecoh-085', category: 'Economics - Synthesis', question: 'Which of the following pairs is INCORRECTLY matched regarding types of goods and the Law of Demand?', options: ['Giffen goods — Exception to Law of Demand', 'Veblen goods — Exception to Law of Demand', 'Substitute goods — Follow the Law of Demand', 'Speculative goods — Follow the Law of Demand strictly'], answer: 3, explanation: 'Speculative goods (like gold) are an EXCEPTION to the Law of Demand — their demand rises even as prices rise, due to expectation of further price increases, not a good that strictly follows the law.' },
  { id: 'ecoh-086', category: 'Economics - Synthesis', question: 'Which of the following pairs is INCORRECTLY matched regarding Five Year Plans?', options: ['Second Five Year Plan — Heavy Industries (Soviet, British, German help)', 'Third Five Year Plan — Failed due to wars and drought', 'Fourth Five Year Plan — MRTP Act and Bank Nationalisation', 'Fifth Five Year Plan — Liberalisation, Privatisation, Globalisation'], answer: 3, explanation: 'The Fifth Five Year Plan (1974-78) is associated with the 20 Point Programme and IDBI financing, NOT the LPG reforms — LPG reforms took place during the Eighth Five Year Plan (1992-97).' },
  { id: 'ecoh-087', category: 'Economics - Synthesis', question: 'Which combination correctly identifies the type of demand elasticity in these two scenarios: (1) A branded shampoo\'s price rises by 5% and its demand falls sharply by 15%. (2) Table salt\'s price rises by 20% but its demand barely changes.', options: ['(1) Elastic demand, (2) Inelastic demand', '(1) Inelastic demand, (2) Elastic demand', '(1) Unitary elastic, (2) Perfectly elastic', '(1) Perfectly inelastic, (2) Perfectly elastic'], answer: 0, explanation: 'Scenario 1 shows Elastic Demand (percentage change in demand > percentage change in price, as the shampoo has substitutes), while Scenario 2 shows Inelastic Demand (salt is a necessity with minimal demand response to price change).' },
  { id: 'ecoh-088', category: 'Economics - Synthesis', question: 'Which of the following correctly ranks these market structures from LEAST competitive to MOST competitive?', options: ['Perfect Competition → Monopolistic Competition → Oligopoly → Monopoly', 'Monopoly → Oligopoly → Monopolistic Competition → Perfect Competition', 'Oligopoly → Monopoly → Perfect Competition → Monopolistic Competition', 'Monopolistic Competition → Perfect Competition → Monopoly → Oligopoly'], answer: 1, explanation: 'The correct ranking from least to most competitive is: Monopoly (single seller, least competitive) → Oligopoly (few large firms) → Monopolistic Competition (many sellers, differentiated products) → Perfect Competition (many sellers, homogeneous products, most competitive).' },
];
